function state(){let raw=localStorage.getItem(KEY);let s=raw?JSON.parse(raw):blankProduction();if(!s.permissions)s.permissions={};if(!Array.isArray(s.documents))s.documents=[];if(!Array.isArray(s.assignments))s.assignments=[];if(!Array.isArray(s.timetable))s.timetable=[];if(!Array.isArray(s.attendance))s.attendance=[];Object.keys(defaultPerms).forEach(r=>{s.permissions[r]=[...new Set([...(s.permissions[r]||[]),...(defaultPerms[r]||[])])]});if(!s.user&&raw===null){s.user=null;save(s)}else if(s.user&&s.user.role&&defaultPerms[s.user.role]){s.user.role=s.user.role}return s} function save(s){localStorage.setItem(KEY,JSON.stringify(s));if(s.user){const cfg=supaCfg();const token=sessionStorage.getItem('dis_access_token');if(cfg?.url&&cfg?.key&&token)directCloudSave(s).catch(()=>{});else syncState(s)}} function esc(x){return String(x??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}

async function productionStatus(){try{return await api('/api/production/status')}catch(e){return {connected:false,message:e.message}}}
function productionBadge(s){if(!s.user||!['Admin','SuperAdmin'].includes(s.user.role))return ''; return `<div id="prodStatus" class="notice"><b>Checking production database…</b><br><span class="muted">Verifying your Supabase connection.</span></div>`}
async function verifyProductionDatabase(){
  const e=document.getElementById('prodStatus');
  if(!e)return;
  e.innerHTML='<b>Checking production database…</b><br><span class="muted">Verifying your Supabase connection.</span>';
  try{
    const cfg=supaCfg();
    const token=sessionStorage.getItem('dis_access_token');
    let source='server';
    if(cfg?.url&&cfg?.key&&token){
      await supaFetch('/rest/v1/rpc/dis_academy_ensure_profile',{method:'POST',body:'{}'}).catch(async err=>{
        // Older repaired databases may not yet have the profile bridge. The
        // state RPC is still a valid production check when the profile exists.
        if(!/function .*does not exist|PGRST202|schema cache/i.test(err.message||''))throw err;
      });
      await directCloudGet();
      source='Supabase';
    }else{
      const d=await productionStatus();
      if(!d.connected)throw new Error(d.message||'Production database could not be verified.');
    }
    const now=new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'});
    e.innerHTML=`<b>Production database: CONNECTED</b> — ${source} is responding.<br><span class="muted">Verified ${esc(now)}.</span> <button class="btn alt" style="margin-left:8px" onclick="verifyProductionDatabase()">Refresh</button>`;
  }catch(err){
    e.innerHTML=`<b>Production database: NOT CONNECTED</b> — ${esc(err.message||'Connection could not be verified.')} <button class="btn alt" style="margin-left:8px" onclick="verifyProductionDatabase()">Retry</button>`;
  }
}
function userObj(s){return s.users.find(u=>u.username===s.user?.username)||s.user}
function can(s,p){let u=userObj(s);if(!u)return false;let list=s.permissions?.[u.role]||[];return list.includes('*')||list.includes(p)}
