const SUPABASE_CFG_KEY='dis_academy_supabase_config_v1';
function supaCfg(){try{return JSON.parse(localStorage.getItem(SUPABASE_CFG_KEY)||'null')}catch{return null}}
function saveSupaCfg(c){localStorage.setItem(SUPABASE_CFG_KEY,JSON.stringify(c))}
async function supaFetch(path,opts={}){const c=supaCfg();if(!c?.url||!c?.key)throw new Error('Supabase is not configured on this device. Enter your Supabase Project URL and Publishable/anon key first.');const token=sessionStorage.getItem('dis_access_token')||c.key;const r=await fetch(c.url.replace(/\/$/,'')+path,{...opts,headers:{'Content-Type':'application/json','apikey':c.key,'Authorization':`Bearer ${token}`,...(opts.headers||{})}});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.msg||d.error_description||d.message||d.hint||d.details||d.message||`Supabase request failed (HTTP ${r.status})`);return d}
function showSupabaseConfig(){document.getElementById('loginForm').style.display='none';document.getElementById('setupForm').style.display='block';const c=supaCfg()||{url:'https://ogysymfjqdrljlgkshkh.supabase.co',key:''};document.getElementById('setupForm').innerHTML=`<div class="notice"><b>Connect this copy of DIS Academy to Supabase</b><br><span class="muted small">This is only needed when opening the ZIP directly without the DIS Academy production server. Never enter your database password or service-role secret here.</span></div><label>Supabase Project URL</label><input id="cfgUrl" class="input" value="${esc(c.url)}" placeholder="https://your-project.supabase.co"><label>Publishable / anon key</label><input id="cfgKey" class="input" value="${esc(c.key)}" placeholder="sb_publishable_…"><button class="btn" onclick="saveSupabaseConfigAndReturn()">Save Supabase Connection</button><button class="btn alt" onclick="login()">Back to sign in</button><p class="muted small">You can find the Project URL and Publishable key in your Supabase project's API settings. The database password and service-role key must never be entered here.</p>`}
function saveSupabaseConfigAndReturn(){const url=document.getElementById('cfgUrl').value.trim(),key=document.getElementById('cfgKey').value.trim();if(!/^https:\/\/[^\s]+\.supabase\.co$/.test(url))return alert('Enter the Supabase Project URL, for example https://your-project.supabase.co');if(!key)return alert('Enter the Supabase Publishable/anon key.');saveSupaCfg({url,key});alert('Supabase connection saved on this device.');login()}
