const DEMO_IDS={students:new Set(['S001','S002','S003']),staff:new Set(['T001','T002','A001','B001']),classes:new Set(['JSS2A','JSS2B']),lessons:new Set(['L001','L002']),assessments:new Set(['A1001','A1002']),users:new Set(['U001','U002','U003','U004','U005','U006','U007']),messages:new Set(['M001','M002','M003']),notifications:new Set(['N001','N002'])};
const DEMO_SUBJECTS=new Set(['Mathematics','English Language','Basic Science','Biology','Chemistry','Physics','Computer Studies']);
const DEMO_STUDENT_NAMES=new Set(['Ada Okafor','Daniel Mensah','Mira Yusuf']);
function clone(x){return JSON.parse(JSON.stringify(x));}
function readJSONKey(k){try{const raw=localStorage.getItem(k);return raw?JSON.parse(raw):null}catch{return null}}
function cleanProductionData(src){
  if(!src||typeof src!=='object')return null;
  const x=clone(src);
  x.user=null;
  x.students=(x.students||[]).filter(v=>v&& !DEMO_IDS.students.has(String(v.id)) && !DEMO_STUDENT_NAMES.has(String(v.name)));
  x.staff=(x.staff||[]).filter(v=>v&& !DEMO_IDS.staff.has(String(v.id)) && !['Mr Sun','Mrs Okafor','D.I.S Academy Admin','Mrs Bursar'].includes(String(v.name)));
  x.users=(x.users||[]).filter(v=>v&& !DEMO_IDS.users.has(String(v.id)) && !['admin','teacher','hod','bursar','staff','parent','student'].includes(String(v.username||'')));
  x.classes=(x.classes||[]).filter(v=>v&& !DEMO_IDS.classes.has(String(v.id)));
  x.lessons=(x.lessons||[]).filter(v=>v&& !DEMO_IDS.lessons.has(String(v.id)));
  x.assessments=(x.assessments||[]).filter(v=>v&& !DEMO_IDS.assessments.has(String(v.id)));
  x.messages=(x.messages||[]).filter(v=>v&& !DEMO_IDS.messages.has(String(v.id)));
  x.notifications=(x.notifications||[]).filter(v=>v&& !DEMO_IDS.notifications.has(String(v.id)));
  x.attendance=(x.attendance||[]).filter(v=>!DEMO_IDS.classes.has(String(v.classId)));
  x.timetable=(x.timetable||[]).filter(v=>!DEMO_IDS.classes.has(String(v.classId)) && !['Mr Sun','Mrs Okafor'].includes(String(v.teacher||'')));
  x.results=(x.results||[]).filter(v=>!DEMO_STUDENT_NAMES.has(String(v.student)));
  x.fees=(x.fees||[]).filter(v=>!DEMO_STUDENT_NAMES.has(String(v.student)));
  x.audit=(x.audit||[]).filter(v=>!['D.I.S Academy Admin','Mr Sun'].includes(String(v.actor||'')) && !['Session activated','Result published','Login'].includes(String(v.action||'')));
  // Recalculate class enrolment counts from the surviving students.
  for(const c of x.classes||[]) c.students=(x.students||[]).filter(st=>String(st.classId)===String(c.id)&&!isArchived(st)).length;
  // Remove orphaned parent/student references left by demo removal.
  const ids=new Set((x.students||[]).map(v=>String(v.id)));
  for(const u of x.users||[]){if(Array.isArray(u.childIds))u.childIds=u.childIds.filter(id=>ids.has(String(id)));}
  x.lessonAssignments=(x.lessonAssignments||[]).filter(a=>!DEMO_IDS.lessons.has(String(a.lessonId)));
  x.assessmentAssignments=(x.assessmentAssignments||[]).filter(a=>!DEMO_IDS.assessments.has(String(a.assessmentId)));
  x.schemaVersion=22;
  return x;
}
function mergeProductionStates(base,extra){
  if(!base)return clone(extra||{}); if(!extra)return clone(base);
  const out=clone(base);
  const mergeBy=(key)=>{const map=new Map((out[key]||[]).map(v=>[String(v?.id??v),v]));for(const v of extra[key]||[]){const k=String(v?.id??v);if(!map.has(k))map.set(k,v);}out[key]=[...map.values()]};
  ['students','staff','users','classes','lessons','assessments','messages','notifications','attendance','fees','timetable','results','audit','lessonAssignments','assessmentAssignments','assignments','documents'].forEach(mergeBy);
  if(Array.isArray(extra.subjects)){const set=new Set(out.subjects||[]);for(const v of extra.subjects)if(!set.has(v))set.add(v);out.subjects=[...set];}
  return out;
}
function looksLikeDemoState(s){if(!s)return true;const counts=[s.students?.length||0,s.staff?.length||0,s.fees?.length||0];return counts[0]<=3&&counts[1]<=4&&counts[2]<=3&&((s.students||[]).some(x=>DEMO_IDS.students.has(String(x.id)))||counts.every(v=>v===0));}
async function ensureSupabaseProfile(){
  const c=supaCfg();
  const token=sessionStorage.getItem('dis_access_token');
  if(!c?.url||!c?.key||!token)throw new Error('Supabase authentication is not available on this device.');
  return await supaFetch('/rest/v1/rpc/dis_academy_ensure_profile',{method:'POST',body:'{}'});
}
async function directCloudGet(){const d=await supaFetch('/rest/v1/rpc/dis_academy_get_state',{method:'POST',body:'{}'});return d||null}
async function directCloudSave(s){const payload=clone(s);payload.user=null;const d=await supaFetch('/rest/v1/rpc/dis_academy_save_state',{method:'POST',body:JSON.stringify({p_state:payload})});return d||payload}
async function recoverLegacyData(){
  if(localStorage.getItem(RECOVERY_KEY)==='complete')return {recovered:false,reason:'already-complete'};
  const legacy=cleanProductionData(readJSONKey(LEGACY_KEY));
  const current=cleanProductionData(readJSONKey(KEY));
  if(!legacy&&!current){localStorage.setItem(RECOVERY_KEY,'complete');return {recovered:false,reason:'no-legacy-data'};}
  const candidate=mergeProductionStates(current,legacy);
  localStorage.setItem(KEY,JSON.stringify({...candidate,user:null}));
  return {recovered:true,state:candidate,legacy:!!legacy};
}
async function productionRecovery(){
  if(!supaCfg()||!sessionStorage.getItem('dis_access_token'))return {cloud:false};
  const rec=await recoverLegacyData();
  let cloud=null;try{cloud=await directCloudGet()}catch(e){return {cloud:false,recovered:rec.recovered,error:e.message};}
  const local=cleanProductionData(readJSONKey(KEY));
  let chosen=cloud && !looksLikeDemoState(cloud)?cleanProductionData(cloud):null;
  if(rec.recovered||!chosen) chosen=mergeProductionStates(chosen,local);
  if(!chosen) chosen=cleanProductionData(fresh());
  const cleaned=cleanProductionData(chosen);
  await directCloudSave(cleaned);
  const s=state();s.user=s.user||null;localStorage.setItem(KEY,JSON.stringify({...cleaned,user:s.user}));
  localStorage.setItem(RECOVERY_KEY,'complete');
  return {cloud:true,recovered:rec.recovered,state:cleaned};
}
function showRecoveryNotice(info){if(!info)return;const n=document.getElementById('recoveryStatus');if(!n)return;if(info.error){n.innerHTML='<b>Production recovery needs setup:</b> '+esc(info.error);return;}if(info.recovered){n.innerHTML='<b>Previous DIS Academy data recovered.</b> Demo students, demo teachers and demo financial figures were excluded.';}else if(info.cloud){n.innerHTML='<b>Production data synchronized.</b> Supabase is now the source of truth.';}}

function login(){document.getElementById('app').innerHTML=`<main class="login card"><img class="logo" src="dis-logo.jpg" onerror="this.src='icon.svg'"><h1>DIS Academy</h1><p class="muted">Powered by SSTRYBE</p><div id="authMode" class="notice">Checking production authentication…</div><div id="recoveryStatus" class="notice" style="display:none"></div><div id="loginForm"><label>Email address</label><input id="u" class="input" type="email" autocomplete="username" placeholder="admin@your-school.com"><label>Password</label><input id="p" class="input" type="password" autocomplete="current-password"><button class="btn" onclick="doLogin()">Sign in</button><p id="loginHelp" class="muted small">Production accounts are authenticated by Supabase Auth when the live server is configured.</p><div class="setup-entry"><hr><p><b>First time setting up DIS Academy?</b></p><button class="btn alt" onclick="showAdminSetup()">Create First Administrator</button><p class="muted small">Use an email address you actually control. You do not need a disacademy.com mailbox yet.</p></div></div><div id="setupForm" style="display:none"></div></main>`;refreshAuthMode();handleAuthLink()} 
function handleAuthLink(){const hash=location.hash.replace(/^#/,'');if(!hash)return;const q=new URLSearchParams(hash),type=q.get('type'),token=q.get('access_token');if(!token||!['invite','recovery','magiclink'].includes(type))return;sessionStorage.setItem('dis_access_token',token);document.getElementById('loginForm').style.display='none';const f=document.getElementById('setupForm');f.style.display='block';f.innerHTML=`<div class="notice"><b>${type==='invite'?'Welcome to DIS Academy':'Set a new DIS Academy password'}</b><br><span class="muted small">Create the password you will use to sign in.</span></div><label>New password</label><input id="linkPassword" class="input" type="password" minlength="8" autocomplete="new-password"><label>Confirm password</label><input id="linkPassword2" class="input" type="password" minlength="8" autocomplete="new-password"><button class="btn" onclick="completeAuthLink()">Set password and continue</button>`;history.replaceState({},document.title,location.pathname+location.search)}
async function completeAuthLink(){const a=document.getElementById('linkPassword')?.value,b=document.getElementById('linkPassword2')?.value;if(!a||a.length<8)return alert('Use at least 8 characters.');if(a!==b)return alert('The passwords do not match.');try{const c=supaCfg();if(!c?.url||!c?.key)throw new Error('Supabase connection is not configured on this device.');const token=sessionStorage.getItem('dis_access_token');const r=await fetch(c.url.replace(/\/$/,'')+'/auth/v1/user',{method:'PUT',headers:{'Content-Type':'application/json','apikey':c.key,'Authorization':`Bearer ${token}`},body:JSON.stringify({password:a})});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.msg||d.message||'Could not set password.');alert('Password created successfully. Sign in with your email and new password.');sessionStorage.removeItem('dis_access_token');login();}catch(e){alert(e.message||'Unable to set password.')}}
async function refreshAuthMode(){try{const h=await api('/api/health');const st=await api('/api/auth/setup-status');const e=document.getElementById('authMode');const help=document.getElementById('loginHelp');if(st.setupRequired&&st.available){e.innerHTML='<b>First-time administrator setup is available</b>';help.textContent='No DIS Academy administrator has been created yet. Use the button below to create the first administrator.';return;}if(h.auth?.configured){e.innerHTML='<b>Production authentication: Supabase Auth</b>';help.textContent='Use the email and password assigned to your DIS Academy account.';}else{e.innerHTML='<b>Demo authentication mode</b>';help.innerHTML='Supabase Auth is not configured on this server yet. The administrator setup form is still available, but it requires the live Supabase connection to create a production account.';document.getElementById('u').type='text';document.getElementById('u').placeholder='admin';}}catch(e){const x=document.getElementById('authMode');if(x)x.innerHTML='<b>DIS Academy setup</b><br>The first administrator button below is available when the production server is connected to Supabase.';}}
function showAdminSetup(){document.getElementById('loginForm').style.display='none';const f=document.getElementById('setupForm');f.style.display='block';f.innerHTML=`<div class="notice"><b>Create your first DIS Academy administrator</b><br><span class="muted small">Use an email address you actually control. You do not need a disacademy.com mailbox yet.</span></div><label>Administrator name</label><input id="setupName" class="input" placeholder="Your name" autocomplete="name"><label>Administrator email</label><input id="setupEmail" class="input" type="email" placeholder="your-real-email@example.com" autocomplete="email"><label>Create password</label><input id="setupPassword" class="input" type="password" minlength="8" autocomplete="new-password"><label>Confirm password</label><input id="setupConfirm" class="input" type="password" minlength="8" autocomplete="new-password"><button class="btn" onclick="createFirstAdmin()">Create Administrator</button><button class="btn alt" onclick="showSupabaseConfig()">Configure Supabase for this device</button><p class="muted small">Your password is sent only to Supabase Auth. DIS Academy does not display or store the password in the school database.</p>`}
async function createFirstAdmin(){const name=document.getElementById('setupName').value.trim(),email=document.getElementById('setupEmail').value.trim(),password=document.getElementById('setupPassword').value,confirmPassword=document.getElementById('setupConfirm').value;if(!name||!email||!password)return alert('Complete all administrator fields.');if(password.length<8)return alert('Use at least 8 characters for the administrator password.');if(password!==confirmPassword)return alert('Passwords do not match.');try{await api('/api/auth/setup-admin',{method:'POST',body:JSON.stringify({name,email,password,confirmPassword})});alert('Administrator created successfully. You can now sign in with the email and password you just created.');location.reload();}catch(e){const cfg=supaCfg();if(cfg&&/fetch|Failed to fetch|not configured|Production database is not connected/i.test(e.message||'')){try{const d=await directFirstAdmin(name,email,password);if(d.user||d.id){alert('Administrator account created in Supabase Auth. Check your email and confirm the account. If the confirmation page cannot open because it points to localhost, return to DIS Academy after clicking the confirmation link and sign in here.');location.reload();return;}}catch(de){return alert('Supabase direct setup failed: '+(de.message||'Unknown error')+'\n\nMake sure the required DIS Academy first-admin migration has been applied to your Supabase project.')}}alert(e.message||'Unable to create administrator.')}}
async function doLogin(){let u=document.getElementById('u').value.trim(),p=document.getElementById('p').value;if(!u||!p)return alert('Enter your login details.');try{const h=await api('/api/health');let d;if(h.auth?.configured){d=await api('/api/auth/login',{method:'POST',body:JSON.stringify({email:u,password:p})});if(d.auth?.accessToken)sessionStorage.setItem('dis_server_access_token',d.auth.accessToken);}else{d=await api('/api/login',{method:'POST',body:JSON.stringify({username:u,password:p})});}let s=state();s=await hydrateFromServer(s);s.user={username:d.user.username||u,name:d.user.name,role:d.user.role,schoolId:d.user.schoolId,id:d.user.id,email:d.user.email,studentId:d.user.studentId,childIds:d.user.childIds,staffId:d.user.staffId,department:d.user.department};save(s);home();}catch(e){try{if(supaCfg()){const d=await directLogin(u,p);sessionStorage.setItem('dis_access_token',d.access_token||'');try{await ensureSupabaseProfile();}catch(pe){console.warn('Profile bridge:',pe.message||pe)}let s=state();s.user={username:d.user.username||u,name:d.user.name,role:d.user.role,schoolId:d.user.schoolId,id:d.user.id,email:d.user.email,studentId:d.user.studentId,childIds:d.user.childIds,staffId:d.user.staffId,department:d.user.department};save(s);try{const box=document.getElementById('recoveryStatus');if(box)box.style.display='block';const info=await productionRecovery();showRecoveryNotice(info);s=state();s.user={username:d.user.username||u,name:d.user.name,role:d.user.role,schoolId:d.user.schoolId,id:d.user.id,email:d.user.email,studentId:d.user.studentId,childIds:d.user.childIds,staffId:d.user.staffId,department:d.user.department};save(s);}catch(re){console.error('Production recovery:',re);const box=document.getElementById('recoveryStatus');if(box){box.style.display='block';box.innerHTML='<b>Data recovery did not complete:</b> '+esc(re.message||re);}}home();return;}}catch(de){if(!navigator.onLine){let s=state(),found=s.users.find(x=>x.username===u||x.email===u);if(found&&p==='1234'){s.user={username:found.username,name:found.name,role:found.role,schoolId:'DIS',id:found.id};save(s);home();return;}}alert(de.message||e.message||'Unable to sign in.');return;}alert(e.message||'Unable to sign in.');}}

async function logout(){
  try{await api('/api/logout',{method:'POST'});}catch(e){console.warn('DIS Academy server logout:',e.message||e)}
  sessionStorage.removeItem('dis_server_access_token');
  const cfg=supaCfg();
  const token=sessionStorage.getItem('dis_access_token');
  try{
    if(cfg?.url&&cfg?.key&&token){
      await fetch(cfg.url.replace(/\/$/,'')+'/auth/v1/logout',{method:'POST',headers:{'apikey':cfg.key,'Authorization':`Bearer ${token}`}});
    }
  }catch(e){console.warn('Supabase logout:',e);}
  sessionStorage.removeItem('dis_access_token');
  sessionStorage.removeItem('dis_academy_authenticated');
  const s=state();
  s.user=null;
  localStorage.setItem(KEY,JSON.stringify(s));
  login();
}

function home(){let s=state();if(!s.user)return login();switch(s.user.role){case'Admin':case'SuperAdmin':return adminHome(s);case'Teacher':return teacherHome(s);case'HOD':return hodHome(s);case'Bursar':return bursarHome(s);case'Staff':return staffHome(s);case'Parent':return parentHome(s);default:return studentHome(s)}}
function stat(label,value){return `<div class="card"><div class="muted">${label}</div><div class="stat">${value}</div></div>`}
function adminHome(s){let total=s.fees.reduce((a,f)=>a+f.amount,0),paid=s.fees.reduce((a,f)=>a+f.paid,0),att=Math.round(s.attendance.reduce((a,x)=>a+x.present,0)/Math.max(1,s.attendance.reduce((a,x)=>a+x.total,0))*100);shell(s,'School Administration',nav(s,'Overview')+`<div class="grid">${stat('Students',s.students.length)}${stat('Staff',s.staff.length)}${stat('Attendance',att+'%')}${stat('Fees collected','₦'+paid.toLocaleString())}</div><div class="card" style="margin-top:14px"><h2>Production data</h2><p>Supabase is the production source of truth. Legacy DIS Academy records are recovered into production without the built-in demo students, demo staff or demo fee figures.</p><button class="btn alt" onclick="runProductionRecovery()">Verify / Recover Previous Data</button><span id="adminRecoveryStatus" class="muted small" style="margin-left:10px"></span></div><div class="grid" style="margin-top:14px"><div class="card"><h2>Administrative control</h2><p>Full school oversight is available to authorized administrators. Teacher, HOD, finance and parent accounts receive scoped dashboards.</p></div><div class="card"><h2>Access model</h2><p><b>Deny by default.</b> Permissions are role-based and resource-scoped.</p></div></div>`)}
async function runProductionRecovery(){const e=document.getElementById('adminRecoveryStatus');if(e)e.textContent='Working…';try{const info=await productionRecovery();if(e)e.textContent=info.recovered?'Previous records recovered; demo data excluded.':'Production data verified.';let s=state();if(s.user)home();}catch(err){if(e)e.textContent='Recovery failed: '+(err.message||err);}}
function teacherHome(s){let u=userObj(s), students=s.students.filter(x=>u.classes?.includes(x.classId));shell(s,'Teacher Dashboard',nav(s,'Overview')+`<div class="grid">${stat('My students',students.length)}${stat('My classes',u.classes?.length||0)}${stat('My subjects',u.subjects?.length||0)}${stat('Open parent messages',visibleMessages(s).filter(m=>m.status==='Open').length)}</div><div class="card" style="margin-top:14px"><h2>My teaching workspace</h2><p>You can manage academic work and communicate with parents of students assigned to you. School finance, staff administration and school settings are not exposed.</p></div>`)}
function hodHome(s){let u=userObj(s),students=s.students.filter(x=>u.classes?.includes(x.classId));shell(s,'HOD Dashboard',nav(s,'Overview')+`<div class="grid">${stat('Department students',students.length)}${stat('Classes',u.classes?.length||0)}${stat('Department results',s.results.filter(r=>students.some(x=>x.name===r.student)).length)}${stat('Open parent messages',visibleMessages(s).filter(m=>m.status==='Open').length)}</div><div class="card" style="margin-top:14px"><h2>Departmental oversight</h2><p>HOD access is limited to assigned department/year-group responsibilities.</p></div>`)}
function bursarHome(s){let total=s.fees.reduce((a,f)=>a+f.amount,0),paid=s.fees.reduce((a,f)=>a+f.paid,0);shell(s,'Finance Dashboard',nav(s,'Overview')+`<div class="grid">${stat('Invoiced','₦'+total.toLocaleString())}${stat('Collected','₦'+paid.toLocaleString())}${stat('Outstanding','₦'+(total-paid).toLocaleString())}</div><div class="card" style="margin-top:14px"><h2>Finance scope</h2><p>This account can manage fees and finance reports, but cannot manage academic results or staff permissions.</p></div>`)}
function staffHome(s){shell(s,'Staff Dashboard',nav(s,'Overview')+`<div class="grid">${stat('Role','School Staff')}${stat('Notifications',userNotifications(s).length)}${stat('Messages',visibleMessages(s).length)}</div><div class="card" style="margin-top:14px"><h2>Operational workspace</h2><p>Your access is limited to the functions assigned to your staff role.</p></div>`)}
function withinAvailability(x){const now=Date.now();if(x?.startAt&&now<new Date(x.startAt).getTime())return false;if(x?.endAt&&now>new Date(x.endAt).getTime())return false;return true}
function availabilityLabel(x){const now=Date.now();if(x?.startAt&&now<new Date(x.startAt).getTime())return 'Scheduled: '+new Date(x.startAt).toLocaleString();if(x?.endAt&&now>new Date(x.endAt).getTime())return 'Closed: '+new Date(x.endAt).toLocaleString();return x?.startAt||x?.endAt?`Open${x.endAt?' until '+new Date(x.endAt).toLocaleString():''}`:'Open now'}
function assignedForStudent(s,st){let lessonIds=(s.lessonAssignments||[]).filter(a=>(a.classIds||[]).includes(st.classId)||(a.studentIds||[]).includes(st.id)).map(a=>a.lessonId);let assessmentIds=(s.assessmentAssignments||[]).filter(a=>(a.classIds||[]).includes(st.classId)||(a.studentIds||[]).includes(st.id)).map(a=>a.assessmentId);let assignmentIds=(s.assignments||[]).filter(a=>(a.status||'Draft')==='Published'&&((a.classIds||[a.classId]).includes(st.classId)||(a.studentIds||[]).includes(st.id))).map(a=>a.id);return {lessons:(s.lessons||[]).filter(l=>lessonIds.includes(l.id)&&withinAvailability(l)),assessments:(s.assessments||[]).filter(a=>assessmentIds.includes(a.id)&&withinAvailability(a)),assignments:(s.assignments||[]).filter(a=>assignmentIds.includes(a.id)&&withinAvailability(a))}}
function studentHome(s){let st=s.students.find(x=>x.id===userObj(s).studentId)||s.students[0],a=assignedForStudent(s,st);shell(s,'Student Dashboard',nav(s,'Overview')+`<div class="grid">${stat('Class',st.classId)}${stat('Average',st.avg+'%')}${stat('Results',s.results.filter(r=>r.student===st.name).length)}${stat('Messages',visibleMessages(s).length)}</div><div class="grid" style="margin-top:14px"><div class="card"><h2>Assigned lessons</h2>${a.lessons.map(l=>`<div class="notice"><b>${esc(l.title)}</b><br>${esc(l.subject)}<br><span class="muted small">${availabilityLabel(l)}</span></div>`).join('')||'<p>No lessons currently available.</p>'}</div><div class="card"><h2>Assigned assessments</h2>${a.assessments.map(x=>`<div class="notice"><b>${esc(x.title)}</b><br>${esc(x.subject)} · ${x.duration||0} minutes<br><span class="muted small">${availabilityLabel(x)}</span></div>`).join('')||'<p>No assessments currently available.</p>'}</div><div class="card"><h2>Assignments</h2>${a.assignments.map(x=>`<div class="notice"><b>${esc(x.title)}</b><br>${esc(x.subject||'—')}<br><span class="muted small">${availabilityLabel(x)}</span></div>`).join('')||'<p>No assignments currently available.</p>'}</div></div>`)}
function parentHome(s){let u=userObj(s),children=s.students.filter(x=>u.childIds?.includes(x.id));shell(s,'Parent Dashboard',nav(s,'Overview')+children.map(c=>`<div class="card"><h2>${esc(c.name)}</h2><p>Class: ${c.classId} · Average: <b>${c.avg}%</b></p><p>Parent access is limited to your child's information and permitted school communications.</p></div>`).join(''))}
function nav(s,current){
  const items=[];
  const add=(label,perm)=>{if(can(s,perm)||s.user?.role==='SuperAdmin')items.push([label, label===current]);};
  add('Overview','school.view');
  add('Students','students.view');
  add('Classes','classes.view');
  add('Subjects','subjects.view');
  add('Lessons','lessons.view');
  add('Assessments','assessments.view');
  if(can(s,'assignments.manage')||can(s,'assignments.manage_assigned'))items.push(['Assignments',current==='Assignments']);
  if(can(s,'attendance.view')||can(s,'attendance.view_assigned'))items.push(['Attendance',current==='Attendance']);
  if(can(s,'fees.view'))items.push(['Fees',current==='Fees']);
  if(can(s,'staff.view'))items.push(['Staff',current==='Staff']);
  if(can(s,'timetable.view')||can(s,'timetable.view_assigned'))items.push(['Timetable',current==='Timetable']);
  if(can(s,'uploads.manage')||can(s,'uploads.manage_assigned'))items.push(['Uploads',current==='Uploads']);
  if(can(s,'session.manage'))items.push(['Session',current==='Session']);
  if(can(s,'reports.view')||can(s,'reports.department')||can(s,'reports.finance'))items.push(['Reports',current==='Reports']);
  if(can(s,'audit.view'))items.push(['Audit',current==='Audit']);
  if(can(s,'messages.view_all')||can(s,'messages.view_assigned_parents')||can(s,'messages.view_department')||can(s,'messages.view_finance')||can(s,'messages.view_child'))items.push(['Messages',current==='Messages']);
  items.push(['Notifications',current==='Notifications']);
  if(can(s,'permissions.manage'))items.push(['Permissions',current==='Permissions']);
  if(can(s,'accounts.manage'))items.push(['Accounts',current==='Accounts']);
  if(can(s,'students.view_assigned'))items.push(['My Students',current==='My Students']);
  if(can(s,'results.view_assigned')||can(s,'results.view'))items.push(['Results',current==='Results']);
  if(s.user?.role==='Parent')items.push(['Child Progress',current==='Child Progress']);
  const seen=new Set();
  return `<nav class="nav">${items.filter(([label])=>!seen.has(label)&&seen.add(label)).map(([label,active])=>`<button type="button" class="${active?'':'alt'}" onclick="page('${label.replace(/'/g,"\\'")}')">${esc(label)}</button>`).join('')}</nav>`;
}
function page(p){let s=state();const map={Overview:home,Students:students,Classes:classes,Subjects:subjects,Lessons:lessons,Assessments:assessments,Attendance:attendance,Fees:fees,Staff:staff,Timetable:timetable,Uploads:uploads,Session:sessionPage,Reports:reports,Audit:audit,Messages:messages,Notifications:notifications,Permissions:permissions,Accounts:accounts,'My Students':myStudents,'Results':results,'Assignments':assignments,'Parent Messages':messages,'Department':department,'Finance Reports':financeReports,'My Attendance':myAttendance,'My Timetable':timetable,'Child Progress':childProgress};if(map[p])return map[p](s);home()}
function guard(s,p){if(!can(s,p)){alert('Access denied for your role.');return false}return true}
function isArchived(x){return !!x?.archivedAt || x?.status==='Archived' || x?.status==='Inactive' || x?.status==='Withdrawn'}
function activeItems(list){return (list||[]).filter(x=>!isArchived(x))}
function archiveRecord(kind,id){let s=state();if(!can(s,'records.manage'))return;let map={student:'students',staff:'staff',class:'classes',lesson:'lessons',assessment:'assessments',assignment:'assignments'};let arr=s[map[kind]]||[];let x=arr.find(v=>v.id===id);if(!x)return;x.archivedAt=new Date().toISOString();x.previousStatus=x.status;x.status='Archived';auditAdd(s,`Archived ${kind} ${x.name||x.title||id}`);save(s);home()}
function restoreRecord(kind,id){let s=state();if(!can(s,'records.manage'))return;let map={student:'students',staff:'staff',class:'classes',lesson:'lessons',assessment:'assessments',assignment:'assignments'};let arr=s[map[kind]]||[];let x=arr.find(v=>v.id===id);if(!x)return;delete x.archivedAt;x.status=x.previousStatus||'Active';delete x.previousStatus;auditAdd(s,`Restored ${kind} ${x.name||x.title||id}`);save(s);home()}
function deleteRecord(kind,id){let s=state();if(!can(s,'records.delete'))return;let map={student:'students',staff:'staff',class:'classes',lesson:'lessons',assessment:'assessments',assignment:'assignments'};let arr=s[map[kind]]||[];let x=arr.find(v=>v.id===id);if(!x)return;let dependent=[];if(kind==='class') dependent=s.students.filter(v=>v.classId===id&&!isArchived(v));if(kind==='student') dependent=(s.results||[]).filter(v=>v.student===x.name);if(dependent.length)return alert(`This record has ${dependent.length} linked academic record(s). Archive it instead of permanently deleting it.`);if(!confirm(`Permanently delete ${x.name||x.title||id}? This cannot be undone.`))return;s[map[kind]]=arr.filter(v=>v.id!==id);if(kind==='lesson')s.lessonAssignments=(s.lessonAssignments||[]).filter(v=>v.lessonId!==id);if(kind==='assessment')s.assessmentAssignments=(s.assessmentAssignments||[]).filter(v=>v.assessmentId!==id);auditAdd(s,`Permanently deleted ${kind} ${x.name||x.title||id}`);save(s);home()}
function lifecycleActions(kind,x){let s=state();let manage=can(s,'records.manage'),del=can(s,'records.delete');if(!manage&&!del)return '<span class="muted small">No action permission</span>';if(isArchived(x))return `<div class="action-bar">${manage?`<button type="button" class="btn alt action-btn" onclick="restoreRecord('${kind}','${x.id}')">↩ Restore</button>`:''}${del?`<button type="button" class="btn danger action-btn" onclick="deleteRecord('${kind}','${x.id}')">✕ Delete permanently</button>`:''}</div>`;return `<div class="action-bar">${manage?`<button type="button" class="btn alt action-btn" onclick="archiveRecord('${kind}','${x.id}')">▣ Archive</button>`:''}${del?`<button type="button" class="btn danger action-btn" onclick="deleteRecord('${kind}','${x.id}')">✕ Delete</button>`:''}</div>`}
function showArchived(kind){let s=state(),map={student:'students',staff:'staff',class:'classes',lesson:'lessons',assessment:'assessments',assignment:'assignments'};let arr=(s[map[kind]]||[]).filter(isArchived);let title=kind.charAt(0).toUpperCase()+kind.slice(1)+' Archive';shell(s,title,nav(s,'Overview')+`<div class="card"><p>Archived records can be restored by an authorized administrator.</p><table class="table"><tr><th>ID</th><th>Name</th><th>Status</th><th>Action</th></tr>${arr.map(x=>`<tr><td>${esc(x.id)}</td><td>${esc(x.name||x.title||'—')}</td><td><span class="pill">Archived</span></td><td>${lifecycleActions(kind,x)}</td></tr>`).join('')||'<tr><td colspan="4">No archived records.</td></tr>'}</table></div>`)}
function studentArchived(){showArchived('student')} function staffArchived(){showArchived('staff')} function classArchived(){showArchived('class')} function lessonArchived(){showArchived('lesson')} function assessmentArchived(){showArchived('assessment')}
function students(s){if(!guard(s,'students.view'))return home();let rows=(s.students||[]).filter(x=>!isArchived(x));shell(s,'Student Records',nav(s,'Students')+`<div class="card"><div class="row"><input id="newStudent" class="input" style="max-width:260px" placeholder="Student name"><select id="newClass" style="max-width:180px">${activeItems(s.classes).map(c=>`<option value="${c.id}">${c.name}</option>`).join('')}</select><button class="btn" onclick="addStudent()">Enroll student</button><button class="btn alt" onclick="studentArchived()">Archived</button></div><table class="table"><tr><th>ID</th><th>Name</th><th>Class</th><th>Parent</th><th>Average</th><th>Action</th></tr>${rows.map(x=>`<tr><td>${esc(x.id)}</td><td>${esc(x.name)}</td><td>${x.classId}</td><td>${esc(x.parent)}</td><td>${x.avg}%</td><td>${lifecycleActions('student',x)}</td></tr>`).join('')}</table></div>`)}
function myStudents(s){if(!guard(s,'students.view_assigned'))return home();let u=userObj(s),rows=s.students.filter(x=>u.classes?.includes(x.classId));shell(s,'My Students',nav(s,'My Students')+`<div class="card"><table class="table"><tr><th>Name</th><th>Class</th><th>Parent</th><th>Average</th></tr>${rows.map(x=>`<tr><td>${esc(x.name)}</td><td>${x.classId}</td><td>${esc(x.parent)}</td><td>${x.avg}%</td></tr>`).join('')}</table></div>`)}
function nextId(prefix,list,field='id'){let n=1;const nums=list.map(x=>String(x[field]||'').match(/(\d+)$/)).filter(Boolean).map(m=>+m[1]);if(nums.length)n=Math.max(...nums)+1;return prefix+String(n).padStart(6,'0')}
function addStudent(){let s=state();if(!guard(s,'students.edit'))return;let name=document.getElementById('newStudent').value.trim(),cid=document.getElementById('newClass').value;if(!name)return;let id=nextId('DIS-STU-',s.students);s.students.push({id,name,classId:cid,avg:0,parent:'Parent not added',parentUser:null,parentPhone:'',admissionNo:id});let c=s.classes.find(x=>x.id===cid);if(c)c.students=(+c.students||0)+1;auditAdd(s,`Enrolled ${name} (${id})`);save(s);students(s)}
function classes(s){if(!guard(s,'classes.view'))return home();let editable=can(s,'classes.edit');let rows=(s.classes||[]).filter(x=>!isArchived(x));shell(s,'Class & Arm Management',nav(s,'Classes')+`<div class="card">${editable?`<h2>Add class / arm</h2><div class="grid"><div><label>Class level</label><input id="classLevel" class="input" placeholder="e.g. JSS 1"></div><div><label>Arm / stream</label><input id="classArm" class="input" placeholder="e.g. A or Science"></div><div><label>Department</label><input id="classDept" class="input" placeholder="Optional"></div><button class="btn" onclick="addClass()">Create class</button></div>`:''}<div class="row" style="margin-top:14px"><button class="btn alt" onclick="classArchived()">Archived classes</button></div><div class="grid" style="margin-top:14px">${rows.map(c=>`<div class="card"><h2>${esc(c.name)}</h2><p>${c.students||0} students</p><p>Class teacher: ${esc(c.teacher||'Not assigned')}</p><p>Department: ${esc(c.department||'—')}</p><div>${lifecycleActions('class',c)}</div></div>`).join('')}</div></div>`)}
function addClass(){let s=state();if(!guard(s,'classes.edit'))return;let level=document.getElementById('classLevel').value.trim(),arm=document.getElementById('classArm').value.trim(),dept=document.getElementById('classDept').value.trim();if(!level)return alert('Enter the class level.');let id=(level.replace(/\s+/g,'').toUpperCase()+(arm?arm.replace(/\s+/g,'').toUpperCase():''));if(s.classes.some(c=>c.id===id))return alert('That class already exists.');s.classes.push({id,name:level+(arm?' '+arm:''),students:0,teacher:'Not assigned',department:dept});auditAdd(s,`Created class ${level}${arm?' '+arm:''}`);save(s);classes(s)}

function attendance(s){if(!(can(s,'attendance.view')||can(s,'attendance.view_assigned')))return home();let u=userObj(s);let rows=(u.role==='Teacher'||u.role==='HOD'||u.role==='Staff')?s.attendance.filter(a=>u.classes?.includes(a.classId)||a.recordedBy===u.id):s.attendance;let editable=can(s,'attendance.edit')||can(s,'attendance.edit_assigned');shell(s,'Attendance Management',nav(s,'Attendance')+`<div class="card"><div class="notice"><b>School attendance is not inferred from app login.</b><br>Platform login/activity may be recorded separately. A teacher or authorized staff member records Present, Late, Absent or Excused for the actual class session.</div>${editable?`<div class="grid"><div><label>Date</label><input id="attDate" class="input" type="date" value="${new Date().toISOString().slice(0,10)}"></div><div><label>Class</label><select id="attClass" class="input" onchange="loadAttendanceRoster()">${activeItems(s.classes).map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></div><div><label>Subject / Period</label><input id="attPeriod" class="input" placeholder="e.g. Mathematics — Period 1"></div><div style="grid-column:1/-1"><label>Student attendance</label><div id="attRoster">Select a class to load the roster.</div></div><button class="btn" onclick="saveAttendanceSession()">Save Attendance</button></div>`:''}<h2 style="margin-top:18px">Attendance records</h2><table class="table"><tr><th>Date</th><th>Class</th><th>Period</th><th>Present</th><th>Late</th><th>Absent</th><th>Excused</th><th>Recorded by</th></tr>${rows.map(a=>`<tr><td>${esc(a.date)}</td><td>${esc(s.classes.find(c=>c.id===a.classId)?.name||a.classId)}</td><td>${esc(a.period||'—')}</td><td>${a.present||0}</td><td>${a.late||0}</td><td>${a.absent||0}</td><td>${a.excused||0}</td><td>${esc(a.recordedByName||a.recordedBy||'—')}</td></tr>`).join('')||'<tr><td colspan="8">No attendance records yet.</td></tr>'}</table></div>`);if(editable)loadAttendanceRoster()}
function loadAttendanceRoster(){const s=state(),cid=document.getElementById('attClass')?.value,box=document.getElementById('attRoster');if(!box||!cid)return;const students=s.students.filter(x=>x.classId===cid&&!isArchived(x));box.innerHTML=students.map(st=>`<div class="row attendance-row"><span style="min-width:220px"><b>${esc(st.name)}</b></span><select id="att_${esc(st.id)}" class="input" style="max-width:180px"><option value="Present">Present</option><option value="Late">Late</option><option value="Absent">Absent</option><option value="Excused">Excused</option></select></div>`).join('')||'<p>No students enrolled in this class.</p>';}
function saveAttendanceSession(){let s=state();if(!(can(s,'attendance.edit')||can(s,'attendance.edit_assigned')))return;let cid=document.getElementById('attClass')?.value,date=document.getElementById('attDate')?.value,period=document.getElementById('attPeriod')?.value.trim()||'General';if(!cid||!date)return alert('Select a date and class.');const students=s.students.filter(x=>x.classId===cid&&!isArchived(x));const records=students.map(st=>({studentId:st.id,name:st.name,status:document.getElementById('att_'+st.id)?.value||'Present'}));let count={Present:0,Late:0,Absent:0,Excused:0};records.forEach(r=>count[r.status]++);s.attendance=s.attendance||[];s.attendance.unshift({id:'ATT'+Date.now(),date,classId:cid,period,records,present:count.Present,late:count.Late,absent:count.Absent,excused:count.Excused,total:students.length,recordedBy:s.user.id,recordedByName:s.user.name});auditAdd(s,`Recorded attendance for ${cid} on ${date}`);save(s);attendance(s)}
function myAttendance(s){return attendance(s)}
function fees(s){if(!guard(s,'fees.view'))return home();let total=s.fees.reduce((a,f)=>a+f.amount,0),paid=s.fees.reduce((a,f)=>a+f.paid,0);shell(s,'Fees & Finance',nav(s,'Fees')+`<div class="grid">${stat('Total invoiced','₦'+total.toLocaleString())}${stat('Collected','₦'+paid.toLocaleString())}${stat('Outstanding','₦'+(total-paid).toLocaleString())}</div><div class="card" style="margin-top:14px">${can(s,'fees.manage')?`<div class="row"><select id="feeStudent">${s.students.map(x=>`<option>${esc(x.name)}</option>`).join('')}</select><input id="feeAmount" class="input" style="max-width:150px" type="number" placeholder="Payment amount"><button class="btn" onclick="recordPayment()">Record payment</button></div>`:''}<table class="table"><tr><th>Student</th><th>Type</th><th>Amount</th><th>Paid</th><th>Balance</th><th>Status</th></tr>${s.fees.map(f=>`<tr><td>${esc(f.student)}</td><td>${f.type}</td><td>₦${f.amount.toLocaleString()}</td><td>₦${f.paid.toLocaleString()}</td><td>₦${(f.amount-f.paid).toLocaleString()}</td><td><span class="pill">${f.status}</span></td></tr>`).join('')}</table></div>`)}
function recordPayment(){let s=state();if(!guard(s,'fees.manage'))return;let name=document.getElementById('feeStudent').value,amount=+document.getElementById('feeAmount').value,f=s.fees.find(x=>x.student===name);if(!f||amount<=0)return;if(f.paid+amount>f.amount)return alert('Payment exceeds outstanding balance.');f.paid+=amount;f.status=f.paid===f.amount?'Paid':'Part Paid';auditAdd(s,`Recorded ₦${amount.toLocaleString()} payment for ${name}`);save(s);fees(s)}
function staff(s){if(!guard(s,'staff.view'))return home();let editable=can(s,'staff.manage'),rows=(s.staff||[]).filter(x=>!isArchived(x));shell(s,'Staff Management',nav(s,'Staff')+`<div class="card">${editable?`<h2>Add staff member</h2><div class="grid"><div><label>Full name</label><input id="staffName" class="input" placeholder="Full name"></div><div><label>Role</label><select id="staffRole" class="input"><option>Teacher</option><option>HOD</option><option>Admin</option><option>Bursar</option><option>Staff</option></select></div><div><label>Department / responsibility</label><input id="staffSubjects" class="input" placeholder="e.g. Science / Mathematics"></div><button class="btn" onclick="addStaff()">Add staff</button></div>`:''}<div class="row" style="margin-top:14px"><button class="btn alt" onclick="staffArchived()">Archived staff</button></div><table class="table"><tr><th>Staff ID</th><th>Name</th><th>Role</th><th>Responsibility</th><th>Status</th><th>Action</th></tr>${rows.map(x=>`<tr><td>${esc(x.id)}</td><td>${esc(x.name)}</td><td>${esc(x.role)}</td><td>${esc(x.subjects)}</td><td><span class="pill">${esc(x.status)}</span></td><td>${lifecycleActions('staff',x)}</td></tr>`).join('')}</table></div>`)}
function addStaff(){let s=state();if(!guard(s,'staff.manage'))return;let name=document.getElementById('staffName').value.trim(),role=document.getElementById('staffRole').value,subjects=document.getElementById('staffSubjects').value.trim();if(!name)return alert('Enter the staff member’s name.');let id=nextId('DIS-STF-',s.staff);s.staff.push({id,name,role,subjects,status:'Active'});auditAdd(s,`Added staff ${name} (${id})`);save(s);staff(s)}

function timetable(s){if(!(can(s,'timetable.view')||can(s,'timetable.view_assigned')))return home();let u=userObj(s),rows=(u.role==='Teacher'||u.role==='Staff')?s.timetable.filter(t=>u.classes?.includes(t.classId)||t.teacherId===u.id||t.teacher===u.name):u.role==='HOD'?s.timetable.filter(t=>u.classes?.includes(t.classId)||t.department===u.department):s.timetable;let editable=can(s,'timetable.manage')||can(s,'timetable.manage_assigned');shell(s,'Timetable Management',nav(s,u.role==='Teacher'?'My Timetable':'Timetable')+`<div class="card"><div class="notice"><b>Timetable builder</b><br>Create periods for classes, assign subjects and teachers, and prevent teacher/class/room clashes before saving.</div>${editable?`<div class="grid"><div><label>Day</label><select id="ttDay" class="input">${['Monday','Tuesday','Wednesday','Thursday','Friday'].map(d=>`<option>${d}</option>`).join('')}</select></div><div><label>Start time</label><input id="ttStart" class="input" type="time" value="08:00"></div><div><label>End time</label><input id="ttEnd" class="input" type="time" value="09:00"></div><div><label>Class</label><select id="ttClass" class="input">${activeItems(s.classes).map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></div><div><label>Subject</label><select id="ttSubject" class="input">${(s.subjects||[]).map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><div><label>Teacher</label><select id="ttTeacher" class="input">${(s.staff||[]).filter(x=>!isArchived(x)&&['Teacher','HOD'].includes(x.role)).map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></div><div><label>Room (optional)</label><input id="ttRoom" class="input" placeholder="e.g. Room 4"></div><button class="btn" onclick="saveTimetableEntry()">Add timetable period</button></div>`:''}<h2 style="margin-top:18px">Schedule</h2><table class="table"><tr><th>Day</th><th>Time</th><th>Class</th><th>Subject</th><th>Teacher</th><th>Room</th><th>Action</th></tr>${rows.sort((a,b)=>(a.day||'').localeCompare(b.day||'')+(a.start||a.time||'').localeCompare(b.start||b.time||'')).map(t=>`<tr><td>${esc(t.day)}</td><td>${esc(t.start||t.time||'')}–${esc(t.end||'')}</td><td>${esc(s.classes.find(c=>c.id===t.classId)?.name||t.classId)}</td><td>${esc(t.subject)}</td><td>${esc(t.teacher||s.staff.find(x=>x.id===t.teacherId)?.name||'')}</td><td>${esc(t.room||'—')}</td><td>${editable?`<button class="btn danger" onclick="deleteTimetableEntry('${t.id}')">Delete</button>`:''}</td></tr>`).join('')||'<tr><td colspan="7">No timetable periods yet.</td></tr>'}</table></div>`)}
function timeOverlap(a,b){return (a.start||a.time||'')<(b.end||b.time||'')&&(b.start||b.time||'')<(a.end||a.time||'')}
function timetableClash(s,e){return (s.timetable||[]).filter(x=>x.day===e.day&&timeOverlap(x,e)&&((x.classId&&x.classId===e.classId)||(x.teacherId&&x.teacherId===e.teacherId)||(x.teacher&&x.teacher===e.teacher)||(x.room&&e.room&&x.room===e.room)))}
function saveTimetableEntry(){let s=state();if(!(can(s,'timetable.manage')||can(s,'timetable.manage_assigned')))return;let e={id:'TT'+Date.now(),day:document.getElementById('ttDay').value,start:document.getElementById('ttStart').value,end:document.getElementById('ttEnd').value,classId:document.getElementById('ttClass').value,subject:document.getElementById('ttSubject').value,teacherId:document.getElementById('ttTeacher').value,teacher:s.staff.find(x=>x.id===document.getElementById('ttTeacher').value)?.name||'',room:document.getElementById('ttRoom').value.trim()};if(e.start>=e.end)return alert('End time must be later than start time.');let clashes=timetableClash(s,e);if(clashes.length)return alert('Timetable clash detected: '+clashes.map(x=>`${x.classId} ${x.start||x.time||''}-${x.end||''} ${x.teacher||''}`).join(' | '));s.timetable=s.timetable||[];s.timetable.push(e);auditAdd(s,`Added timetable period ${e.day} ${e.start}-${e.end}`);save(s);timetable(s)}
function deleteTimetableEntry(id){let s=state();if(!(can(s,'timetable.manage')||can(s,'timetable.manage_assigned')))return;s.timetable=(s.timetable||[]).filter(x=>x.id!==id);auditAdd(s,`Deleted timetable period ${id}`);save(s);timetable(s)}
function sessionPage(s){if(!guard(s,'session.manage'))return home();shell(s,'Academic Session & Term',nav(s,'Session')+`<div class="card"><p>${esc(s.session.year)} · ${esc(s.session.term)} · ${esc(s.session.start)} to ${esc(s.session.end)} · <span class="pill">${esc(s.session.status)}</span></p><button class="btn" onclick="toggleSession()">${s.session.status==='Active'?'Close':'Activate'} session</button></div>`)} function toggleSession(){let s=state();s.session.status=s.session.status==='Active'?'Closed':'Active';auditAdd(s,`${s.session.status} academic session`);save(s);sessionPage(s)}
function reports(s){if(!guard(s,'reports.view'))return home();shell(s,'School Reports',nav(s,'Reports')+`<div class="grid">${stat('Enrollment',s.students.length)}${stat('Attendance',Math.round(s.attendance.reduce((a,x)=>a+x.present,0)/Math.max(1,s.attendance.reduce((a,x)=>a+x.total,0))*100)+'%')}${stat('Fees collected','₦'+s.fees.reduce((a,f)=>a+f.paid,0).toLocaleString())}</div><div class="card" style="margin-top:14px"><button class="btn" onclick="window.print()">Print / Save PDF</button></div>`)}
function financeReports(s){if(!guard(s,'reports.finance'))return home();shell(s,'Finance Reports',nav(s,'Finance Reports')+`<div class="grid">${stat('Collected','₦'+s.fees.reduce((a,f)=>a+f.paid,0).toLocaleString())}${stat('Outstanding','₦'+s.fees.reduce((a,f)=>a+f.amount-f.paid,0).toLocaleString())}</div>`)}
function audit(s){if(!guard(s,'audit.view'))return home();shell(s,'Audit Log',nav(s,'Audit')+`<div class="card"><table class="table"><tr><th>Date</th><th>Actor</th><th>Action</th></tr>${s.audit.map(x=>`<tr><td>${esc(x.date)}</td><td>${esc(x.actor)}</td><td>${esc(x.action)}</td></tr>`).join('')}</table></div>`)}
function results(s){if(!(can(s,'results.view')||can(s,'results.view_assigned')))return home();let u=userObj(s),rows=(u.role==='Teacher'||u.role==='HOD')?s.results.filter(r=>u.classes?.includes(r.class)):s.results;shell(s,'Results',nav(s,'Results')+`<div class="card"><table class="table"><tr><th>Student</th><th>Class</th><th>Assessment</th><th>Score</th><th>Topic</th><th>Date</th></tr>${rows.map(r=>`<tr><td>${esc(r.student)}</td><td>${r.class}</td><td>${esc(r.assessment)}</td><td>${r.score}%</td><td>${esc(r.topic)}</td><td>${r.date}</td></tr>`).join('')}</table></div>`)}
function assignmentTargetControls(s,current){let x=current||{classIds:[],studentIds:[]};return `<div class="grid"><div><label>Assign to classes</label><select id="assignmentClasses" class="input" multiple size="5">${activeItems(s.classes).map(c=>`<option value="${esc(c.id)}" ${x.classIds?.includes(c.id)||x.classId===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div><label>Assign to individual students</label><select id="assignmentStudents" class="input" multiple size="5">${activeItems(s.students).map(st=>`<option value="${esc(st.id)}" ${x.studentIds?.includes(st.id)?'selected':''}>${esc(st.name)} — ${esc(st.classId)}</option>`).join('')}</select></div></div>`}
function availabilityControls(x,prefix){x=x||{};return `<div class="grid"><div><label>Available from</label><input id="${prefix}Start" class="input" type="datetime-local" value="${x.startAt?new Date(x.startAt).toISOString().slice(0,16):''}"></div><div><label>Available until</label><input id="${prefix}End" class="input" type="datetime-local" value="${x.endAt?new Date(x.endAt).toISOString().slice(0,16):''}"></div></div><p class="muted small">Leave either field blank for no limit. This can be an exact day/time or a multi-day availability window.</p>`}
async function uploadDocument(file,entityType,entityId){
 const s=state();if(!file)throw new Error('Choose a Word document first.');if(!/\.docx?$/i.test(file.name))throw new Error('Only .doc and .docx files are supported.');if(file.size>15*1024*1024)throw new Error('Document is too large. Maximum size is 15 MB.');
 const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(new Error('Could not read the document.'));r.readAsDataURL(file)});
 const d=await api('/api/documents/upload',{method:'POST',body:JSON.stringify({name:file.name,size:file.size,mime:file.type||'application/vnd.openxmlformats-officedocument.wordprocessingml.document',entityType,entityId,data})});
 s.documents=s.documents||[];s.documents=s.documents.filter(x=>!(x.entityType===entityType&&x.entityId===entityId));s.documents.unshift(d.document);save(s);return d.document;
}
async function downloadDocument(id){try{const base=(window.DIS_API_BASE_URL||localStorage.getItem('DIS_API_BASE_URL')||'').trim().replace(/\/$/,''); if(!base) throw new Error('DIS Academy production API URL is not configured.');const token=sessionStorage.getItem('dis_server_access_token')||'';const r=await fetch(base+'/api/documents/download/'+encodeURIComponent(id),{credentials:'include',headers:{'X-DIS-App':'android-2.2.4',...(token?{Authorization:`Bearer ${token}`}:{})}});if(!r.ok)throw new Error((await r.text())||('HTTP '+r.status));const blob=await r.blob();const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=(r.headers.get('Content-Disposition')?.match(/filename=\"?([^\"]+)/i)?.[1]||'DIS-Academy-document.docx');a.target='_blank';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}catch(e){alert(e.message||'Unable to download document.')}}
function refreshUploadRecords(){const type=document.getElementById('upType')?.value,sel=document.getElementById('upRecord');if(!sel)return;const s=state(),arr=type==='assessment'?s.assessments||[]:s.assignments||[];sel.innerHTML=arr.filter(x=>!isArchived(x)).map(x=>`<option value="${esc(x.id)}">${esc(x.title)}</option>`).join('')||'<option value="">No records available</option>'}
async function uploadFromCentre(){const type=document.getElementById('upType')?.value,id=document.getElementById('upRecord')?.value,f=document.getElementById('upFile')?.files?.[0],box=document.getElementById('uploadStatus');if(!id)return alert('Select an assessment or assignment.');if(!f)return alert('Choose a Word document first.');if(box){box.style.display='block';box.textContent='Uploading…'}try{await uploadDocument(f,type,id);if(box)box.textContent='Document uploaded successfully. It can now be opened/downloaded from the relevant assessment or assignment.';uploads(state())}catch(e){if(box)box.textContent='Upload failed: '+(e.message||e)}}

function attachmentList(s,kind,id){return (s.documents||[]).filter(d=>d.entityType===kind&&d.entityId===id).map(d=>`<div class="notice"><b>${esc(d.name)}</b> <span class="muted small">(${Math.round((d.size||0)/1024)} KB)</span><br><button class="btn alt" onclick="downloadDocument('${d.id}')">Open / download</button></div>`).join('')||'<p class="muted small">No document uploaded.</p>'}
function assignments(s){if(!(can(s,'assignments.manage')||can(s,'assignments.manage_assigned')))return home();let rows=(s.assignments||[]).filter(x=>!isArchived(x));let editable=can(s,'assignments.manage')||can(s,'assignments.manage_assigned');shell(s,'Assignments',nav(s,'Assignments')+`<div class="card"><h2>Assignment Centre</h2><p class="muted">Type the assignment here, or attach a Word document. Existing assignments can be edited after publishing.</p>${editable?`<div class="grid"><div><label>Title</label><input id="assignmentTitle" class="input" placeholder="e.g. Algebra Practice"></div><div><label>Subject</label><select id="assignmentSubject" class="input">${s.subjects.map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><div style="grid-column:1/-1"><label>Instructions / questions</label><textarea id="assignmentContent" class="input" rows="8" placeholder="Type the assignment questions and instructions here..."></textarea></div><div style="grid-column:1/-1">${assignmentTargetControls(s)}${availabilityControls({},'assignment')}</div><div style="grid-column:1/-1"><label>Optional Word document</label><input id="assignmentCreateFile" class="input" type="file" accept=".doc,.docx,application/msword,application/vnd.openxmlformats-officedocument.wordprocessingml.document"></div><button class="btn" onclick="createAssignment()">Create assignment</button></div>`:''}<div class="row" style="margin-top:14px"><button class="btn alt" onclick="showArchivedAssignments()">Archived assignments</button><button class="btn alt" onclick="page('Uploads')">Open Upload Centre</button></div><h3 style="margin-top:18px">Existing assignments</h3><table class="table"><tr><th>Title</th><th>Subject</th><th>Audience</th><th>Availability</th><th>Status</th><th>Action</th></tr>${rows.map(a=>`<tr><td>${esc(a.title)}</td><td>${esc(a.subject||'—')}</td><td>${esc((a.classIds||[a.classId]).filter(Boolean).map(id=>s.classes.find(c=>c.id===id)?.name||id).join(', '))}${a.studentIds?.length?` + ${a.studentIds.length} student(s)`:''}</td><td>${esc(availabilityLabel(a))}</td><td><span class="pill">${esc(a.status||'Draft')}</span></td><td><button class="btn" onclick="editAssignment('${a.id}')">Edit</button> <button class="btn alt" onclick="togglePublish('assignment','${a.id}')">${a.status==='Published'?'Unpublish':'Publish'}</button> ${lifecycleActions('assignment',a)}</td></tr>`).join('')||'<tr><td colspan="6">No assignments yet.</td></tr>'}</table></div>`)}
async function createAssignment(){let s=state();if(!(can(s,'assignments.manage')||can(s,'assignments.manage_assigned')))return;let x={id:'AS'+Date.now(),title:document.getElementById('assignmentTitle').value.trim(),subject:document.getElementById('assignmentSubject').value,content:document.getElementById('assignmentContent').value.trim(),classIds:selectedValues('assignmentClasses'),studentIds:selectedValues('assignmentStudents'),startAt:document.getElementById('assignmentStart').value?new Date(document.getElementById('assignmentStart').value).toISOString():null,endAt:document.getElementById('assignmentEnd').value?new Date(document.getElementById('assignmentEnd').value).toISOString():null,status:'Draft',versions:[]};if(!x.title)return alert('Enter an assignment title.');if(!x.content&&!document.getElementById('assignmentCreateFile')?.files?.length)return alert('Type the assignment content or attach a Word document.');if(!x.classIds.length&&!x.studentIds.length)return alert('Assign the assignment to at least one class or student.');if(x.startAt&&x.endAt&&x.startAt>=x.endAt)return alert('The end time must be later than the start time.');s.assignments=s.assignments||[];s.assignments.unshift(x);auditAdd(s,`Created assignment ${x.title}`);save(s);let f=document.getElementById('assignmentCreateFile')?.files?.[0];if(f){try{await uploadDocument(f,'assignment',x.id)}catch(e){alert('Assignment created, but Word upload failed: '+e.message)}}editAssignment(x.id)}
function editAssignment(id){let s=state(),x=(s.assignments||[]).find(a=>a.id===id);if(!x)return;let editable=can(s,'assignments.manage')||can(s,'assignments.manage_assigned');shell(s,'Edit Assignment',nav(s,'Assignments')+`<div class="card"><div class="notice"><b>Editing mode.</b> You can correct the assignment after publishing, change its targets and availability, and replace/add a Word document.</div><div class="grid"><div><label>Title</label><input id="eaTitle" class="input" value="${esc(x.title)}"></div><div><label>Subject</label><select id="eaSubject" class="input">${s.subjects.map(v=>`<option ${v===x.subject?'selected':''}>${esc(v)}</option>`).join('')}</select></div><div style="grid-column:1/-1"><label>Instructions / questions</label><textarea id="eaContent" class="input" rows="8">${esc(x.content||'')}</textarea></div><div style="grid-column:1/-1">${assignmentTargetControls(s,{classIds:x.classIds||[x.classId],studentIds:x.studentIds||[]})}${availabilityControls(x,'ea')}</div><div style="grid-column:1/-1"><h3>Word document</h3>${attachmentList(s,'assignment',x.id)}<input id="eaFile" class="input" type="file" accept=".doc,.docx,application/msword,application/vnd.openxmlformats-officedocument.wordprocessingml.document"><button class="btn alt" onclick="uploadForRecord('eaFile','assignment','${x.id}')">Upload Word document</button></div></div><div class="row" style="margin-top:12px"><button class="btn" onclick="saveAssignmentEdit('${x.id}')">Save changes</button><button class="btn alt" onclick="togglePublish('assignment','${x.id}')">${x.status==='Published'?'Unpublish':'Publish'}</button></div><div class="notice"><b>Version history:</b> ${(x.versions||[]).length} saved version(s).</div></div>`)}
function saveAssignmentEdit(id){let s=state(),x=s.assignments.find(a=>a.id===id);if(!x)return;let old=clone(x);delete old.versions;x.versions=x.versions||[];x.versions.unshift({...old,savedAt:new Date().toISOString()});x.title=document.getElementById('eaTitle').value.trim();x.subject=document.getElementById('eaSubject').value;x.content=document.getElementById('eaContent').value.trim();x.classIds=selectedValues('assignmentClasses');x.studentIds=selectedValues('assignmentStudents');x.startAt=document.getElementById('eaStart').value?new Date(document.getElementById('eaStart').value).toISOString():null;x.endAt=document.getElementById('eaEnd').value?new Date(document.getElementById('eaEnd').value).toISOString():null;if(!x.title)return alert('Title is required.');if(!x.classIds.length&&!x.studentIds.length)return alert('Assign to at least one class or student.');if(x.startAt&&x.endAt&&x.startAt>=x.endAt)return alert('The end time must be later than the start time.');auditAdd(s,`Edited assignment ${x.title}`);save(s);editAssignment(id)}
function showArchivedAssignments(){let s=state(),arr=(s.assignments||[]).filter(isArchived);shell(s,'Archived Assignments',nav(s,'Assignments')+`<div class="card"><table class="table"><tr><th>ID</th><th>Title</th><th>Status</th><th>Action</th></tr>${arr.map(x=>`<tr><td>${esc(x.id)}</td><td>${esc(x.title)}</td><td><span class="pill">Archived</span></td><td>${lifecycleActions('assignment',x)}</td></tr>`).join('')||'<tr><td colspan="4">No archived assignments.</td></tr>'}</table></div>`)}
function subjects(s){if(!guard(s,'subjects.view'))return home();let editable=can(s,'subjects.manage')||can(s,'assignments.manage')||can(s,'assignments.manage_assigned');let archived=new Set(s.archivedSubjects||[]);let rows=(s.subjects||[]).filter(x=>!archived.has(x));shell(s,'Subjects',nav(s,'Subjects')+`<div class="card"><h2>Subject catalogue</h2>${editable?`<div class="row"><input id="subjectName" class="input" placeholder="Subject name"><button class="btn" onclick="addSubject()">Add subject</button></div>`:''}<div class="row" style="margin-top:14px"><button class="btn alt" onclick="showArchivedSubjects()">Archived subjects</button></div><table class="table"><tr><th>Subject</th><th>Lessons</th><th>Assessments</th><th>Action</th></tr>${rows.map(x=>`<tr><td>${esc(x)}</td><td>${(s.lessons||[]).filter(l=>l.subject===x&&!isArchived(l)).length}</td><td>${(s.assessments||[]).filter(a=>a.subject===x&&!isArchived(a)).length}</td><td>${editable?`<button class="btn alt" onclick="archiveSubject('${esc(x).replace(/'/g,"\\'")}')">Archive</button>${can(s,'records.delete')?` <button class="btn danger" onclick="deleteSubject('${esc(x).replace(/'/g,"\\'")}')">Delete</button>`:''}`:''}</td></tr>`).join('')}</table></div>`)}
function archiveSubject(name){let s=state();if(!can(s,'subjects.manage'))return;s.archivedSubjects=[...new Set([...(s.archivedSubjects||[]),name])];auditAdd(s,`Archived subject ${name}`);save(s);subjects(s)}
function restoreSubject(name){let s=state();if(!can(s,'records.manage'))return;s.archivedSubjects=(s.archivedSubjects||[]).filter(x=>x!==name);auditAdd(s,`Restored subject ${name}`);save(s);subjects(s)}
function deleteSubject(name){let s=state();if(!can(s,'records.delete'))return;let deps=(s.lessons||[]).filter(x=>x.subject===name&&!isArchived(x)).length+(s.assessments||[]).filter(x=>x.subject===name&&!isArchived(x)).length;if(deps)return alert(`This subject has ${deps} active lesson/assessment record(s). Archive the subject instead.`);if(!confirm(`Permanently delete subject ${name}?`))return;s.subjects=(s.subjects||[]).filter(x=>x!==name);s.archivedSubjects=(s.archivedSubjects||[]).filter(x=>x!==name);auditAdd(s,`Permanently deleted subject ${name}`);save(s);subjects(s)}
function showArchivedSubjects(){let s=state(),rows=s.archivedSubjects||[];shell(s,'Archived Subjects',nav(s,'Subjects')+`<div class="card"><table class="table"><tr><th>Subject</th><th>Action</th></tr>${rows.map(x=>`<tr><td>${esc(x)}</td><td><button class="btn alt" onclick="restoreSubject('${esc(x).replace(/'/g,"\\'")}')">Restore</button>${can(s,'records.delete')?` <button class="btn danger" onclick="deleteSubject('${esc(x).replace(/'/g,"\\'")}')">Delete</button>`:''}</td></tr>`).join('')||'<tr><td colspan="2">No archived subjects.</td></tr>'}</table></div>`)}
function addSubject(){let s=state();if(!can(s,'subjects.manage'))return alert('Only authorized administrators can add subjects.');let v=document.getElementById('subjectName').value.trim();if(!v)return;if(s.subjects.some(x=>x.toLowerCase()===v.toLowerCase()))return alert('Subject already exists.');s.subjects.push(v);auditAdd(s,`Added subject ${v}`);save(s);subjects(s)}
function targetControls(prefix,s,current){let selected=current||{classIds:[],studentIds:[]};return `<div class="grid"><div><label>Assign to classes</label><select id="${prefix}Classes" class="input" multiple size="5">${s.classes.map(c=>`<option value="${esc(c.id)}" ${selected.classIds?.includes(c.id)?'selected':''}>${esc(c.name)}</option>`).join('')}</select><small class="muted">Hold Ctrl/long-press to select multiple.</small></div><div><label>Assign to individual students (optional)</label><select id="${prefix}Students" class="input" multiple size="5">${s.students.map(x=>`<option value="${esc(x.id)}" ${selected.studentIds?.includes(x.id)?'selected':''}>${esc(x.name)} — ${esc(x.classId)}</option>`).join('')}</select></div></div>`}
function selectedValues(id){return [...(document.getElementById(id)?.selectedOptions||[])].map(o=>o.value)}
function lessons(s){if(!(can(s,'lessons.view')||can(s,'assignments.manage')||can(s,'assignments.manage_assigned')))return home();let editable=can(s,'lessons.manage')||can(s,'assignments.manage')||can(s,'assignments.manage_assigned');let rows=(s.lessons||[]).filter(x=>!isArchived(x));shell(s,'Lessons & Learning Content',nav(s,'Lessons')+`<div class="card"><h2>Learning content</h2>${editable?`<div class="grid"><div><label>Subject</label><select id="lessonSubject" class="input">${s.subjects.map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><div><label>Lesson title</label><input id="lessonTitle" class="input" placeholder="e.g. Introduction to Algebra"></div><div style="grid-column:1/-1"><label>Lesson content</label><textarea id="lessonContent" class="input" rows="7" placeholder="Write the lesson content..."></textarea></div><div style="grid-column:1/-1">${targetControls('lesson',s)}</div><div style="grid-column:1/-1"><label>Optional Word document</label><input id="lessonFile" class="input" type="file" accept=".doc,.docx,application/msword,application/vnd.openxmlformats-officedocument.wordprocessingml.document"></div><button class="btn" onclick="addLesson()">Save and assign lesson</button></div>`:''}<div class="row" style="margin-top:14px"><button class="btn alt" onclick="lessonArchived()">Archived lessons</button></div><h3 style="margin-top:18px">Existing lessons</h3><table class="table"><tr><th>Subject</th><th>Lesson</th><th>Audience</th><th>Status</th><th>Action</th></tr>${rows.map(l=>{let a=(s.lessonAssignments||[]).find(x=>x.lessonId===l.id)||{classIds:[],studentIds:[]};return `<tr><td>${esc(l.subject)}</td><td>${esc(l.title)}</td><td>${esc((a.classIds||[]).map(id=>s.classes.find(c=>c.id===id)?.name||id).join(', '))}${a.studentIds?.length?` + ${a.studentIds.length} student(s)`:''}</td><td><span class="pill">${esc(l.status||'Draft')}</span></td><td>${editable?`<button class="btn" onclick="editLesson('${l.id}')">Edit</button> `:''}${lifecycleActions('lesson',l)}</td></tr>`}).join('')||'<tr><td colspan="5">No lessons yet.</td></tr>'}</table></div>`)}
function editLesson(id){let s=state(),l=(s.lessons||[]).find(x=>x.id===id);if(!l)return;let a=(s.lessonAssignments||[]).find(x=>x.lessonId===id)||{classIds:[],studentIds:[]};shell(s,'Edit Lesson',nav(s,'Lessons')+`<div class="card"><div class="grid"><div><label>Subject</label><select id="elSubject" class="input">${s.subjects.map(v=>`<option ${v===l.subject?'selected':''}>${esc(v)}</option>`).join('')}</select></div><div><label>Lesson title</label><input id="elTitle" class="input" value="${esc(l.title)}"></div><div style="grid-column:1/-1"><label>Lesson content</label><textarea id="elContent" class="input" rows="10">${esc(l.content||'')}</textarea></div><div style="grid-column:1/-1">${targetControls('lessonEdit',s,a)}</div><div style="grid-column:1/-1"><h3>Word document</h3>${attachmentList(s,'lesson',id)}<input id="elFile" class="input" type="file" accept=".doc,.docx,application/msword,application/vnd.openxmlformats-officedocument.wordprocessingml.document"><button class="btn alt" onclick="uploadForRecord('elFile','lesson','${id}')">Upload Word document</button></div></div><div class="row" style="margin-top:14px"><button class="btn" onclick="saveLessonEdit('${id}')">Save changes</button><button class="btn alt" onclick="lessons(state())">Back to Lessons</button></div></div>`)}
function saveLessonEdit(id){let s=state(),l=(s.lessons||[]).find(x=>x.id===id);if(!l)return;let title=document.getElementById('elTitle').value.trim(),content=document.getElementById('elContent').value.trim(),subject=document.getElementById('elSubject').value,classIds=selectedValues('lessonEditClasses'),studentIds=selectedValues('lessonEditStudents');if(!title||!content)return alert('Lesson title and content are required.');if(!classIds.length&&!studentIds.length)return alert('Assign the lesson to at least one class or student.');l.subject=subject;l.title=title;l.content=content;s.lessonAssignments=s.lessonAssignments||[];let a=s.lessonAssignments.find(x=>x.lessonId===id);if(a){a.classIds=classIds;a.studentIds=studentIds}else{s.lessonAssignments.unshift({lessonId:id,classIds,studentIds})}auditAdd(s,`Edited lesson ${title}`);save(s);let f=document.getElementById('elFile')?.files?.[0];if(f)uploadDocument(f,'lesson',id).catch(e=>alert('Lesson saved, but Word upload failed: '+e.message));lessons(s)}
async function addLesson(){let s=state();if(!(can(s,'lessons.manage')||can(s,'assignments.manage')||can(s,'assignments.manage_assigned')))return;let subject=document.getElementById('lessonSubject').value,title=document.getElementById('lessonTitle').value.trim(),content=document.getElementById('lessonContent').value.trim(),classIds=selectedValues('lessonClasses'),studentIds=selectedValues('lessonStudents');if(!title||!content)return alert('Enter a lesson title and content.');if(!classIds.length&&!studentIds.length)return alert('Assign the lesson to at least one class or student.');s.lessons=s.lessons||[];let id='L'+Date.now();s.lessons.unshift({id,subject,title,content,status:'Published',versions:[]});s.lessonAssignments=s.lessonAssignments||[];s.lessonAssignments.unshift({lessonId:id,classIds,studentIds});auditAdd(s,`Created lesson ${title} and assigned it`);save(s);let f=document.getElementById('lessonFile')?.files?.[0];if(f){try{await uploadDocument(f,'lesson',id)}catch(e){alert('Lesson created, but Word upload failed: '+e.message)}}lessons(s)}
function questionRow(q,i){q=q||{};return `<div class="card question-row"><div class="row"><b>Question ${i+1}</b><button class="btn danger" onclick="removeAssessmentQuestion(${i})">Remove</button></div><label>Type</label><select id="qType${i}" class="input"><option ${q.type==='mcq'?'selected':''} value="mcq">Multiple choice</option><option ${q.type==='true_false'?'selected':''} value="true_false">True / False</option><option ${q.type==='short_answer'?'selected':''} value="short_answer">Short answer</option><option ${q.type==='numerical'?'selected':''} value="numerical">Numerical</option><option ${q.type==='fill_blank'?'selected':''} value="fill_blank">Fill in the blank</option></select><label>Question text</label><textarea id="qText${i}" class="input" rows="3">${esc(q.text||'')}</textarea><div class="grid"><div><label>Marks</label><input id="qMarks${i}" class="input" type="number" min="1" value="${q.marks||1}"></div><div><label>Difficulty</label><select id="qDiff${i}" class="input"><option ${q.difficulty==='Easy'?'selected':''}>Easy</option><option ${q.difficulty==='Medium'||!q.difficulty?'selected':''}>Medium</option><option ${q.difficulty==='Hard'?'selected':''}>Hard</option></select></div></div><label>Options (for MCQ, one per line)</label><textarea id="qOptions${i}" class="input" rows="4">${esc((q.options||[]).join('\n'))}</textarea><label>Correct answer</label><input id="qAnswer${i}" class="input" value="${esc(q.answer||'')}"><label>Explanation (optional)</label><textarea id="qExplanation${i}" class="input" rows="2">${esc(q.explanation||'')}</textarea></div>`}
function assessmentEditor(id){window.currentAssessmentEditorId=id;let s=state(),a=s.assessments.find(x=>x.id===id);if(!a)return;let editable=can(s,'assessments.manage')||can(s,'assignments.manage')||can(s,'assignments.manage_assigned');shell(s,'Edit Assessment',nav(s,'Assessments')+`<div class="card"><div class="notice"><b>Editing mode.</b> Changes here can be saved before or after publishing. Questions, answers, marks, assignments, availability and Word attachments can all be corrected.</div><div class="grid"><div><label>Title</label><input id="aeTitle" class="input" value="${esc(a.title)}"></div><div><label>Subject</label><select id="aeSubject" class="input">${s.subjects.map(v=>`<option ${v===a.subject?'selected':''}>${esc(v)}</option>`).join('')}</select></div><div><label>Duration (minutes)</label><input id="aeDuration" class="input" type="number" min="1" value="${a.duration||30}"></div><div><label>Pass mark (%)</label><input id="aePass" class="input" type="number" min="0" max="100" value="${a.passMark??50}"></div><div style="grid-column:1/-1">${assignmentTargetControls(s,{classIds:a.classIds||[],studentIds:a.studentIds||[]}).replace(/assignmentClasses/g,'assessmentClasses').replace(/assignmentStudents/g,'assessmentStudents')}</div><div style="grid-column:1/-1">${availabilityControls(a,'ae')}</div><div style="grid-column:1/-1"><h3>Questions</h3><div id="questionList">${(a.questionBank||[]).map((q,i)=>questionRow(q,i)).join('')||'<p class="muted">No questions yet. Add your first question.</p>'}</div><button class="btn alt" onclick="addAssessmentQuestion()">+ Add question</button></div><div style="grid-column:1/-1"><h3>Word document</h3>${attachmentList(s,'assessment',a.id)}<input id="aeFile" class="input" type="file" accept=".doc,.docx,application/msword,application/vnd.openxmlformats-officedocument.wordprocessingml.document"><button class="btn alt" onclick="uploadForRecord('aeFile','assessment','${a.id}')">Upload Word document</button></div></div><div class="row" style="margin-top:14px"><button class="btn" onclick="saveAssessmentEdit('${a.id}')">Save changes</button><button class="btn alt" onclick="togglePublish('assessment','${a.id}')">${a.status==='Published'?'Unpublish':'Publish'}</button></div><div class="notice"><b>Questions:</b> ${(a.questionBank||[]).length} · <b>Marks:</b> ${(a.questionBank||[]).reduce((n,q)=>n+(Number(q.marks)||0),0)} · <b>Versions:</b> ${(a.versions||[]).length}</div></div>`)}
function assessmentCreateQuestionRow(q,i){q=q||{type:'mcq',text:'',marks:1,difficulty:'Medium',options:['Option A','Option B'],answer:'',explanation:''};return `<div class="card question-row" id="createQuestion${i}"><div class="row"><b>Question ${i+1}</b><button type="button" class="btn danger" onclick="removeAssessmentCreateQuestion(${i})">Remove</button></div><label>Question type</label><select id="cQType${i}" class="input"><option value="mcq" ${q.type==='mcq'?'selected':''}>Multiple choice</option><option value="true_false" ${q.type==='true_false'?'selected':''}>True / False</option><option value="short_answer" ${q.type==='short_answer'?'selected':''}>Short answer</option><option value="numerical" ${q.type==='numerical'?'selected':''}>Numerical</option><option value="fill_blank" ${q.type==='fill_blank'?'selected':''}>Fill in the blank</option></select><label>Question text</label><textarea id="cQText${i}" class="input" rows="4" placeholder="Type the question here...">${esc(q.text||'')}</textarea><div class="grid"><div><label>Marks</label><input id="cQMarks${i}" class="input" type="number" min="1" value="${q.marks||1}"></div><div><label>Difficulty</label><select id="cQDiff${i}" class="input"><option ${q.difficulty==='Easy'?'selected':''}>Easy</option><option ${q.difficulty==='Medium'||!q.difficulty?'selected':''}>Medium</option><option ${q.difficulty==='Hard'?'selected':''}>Hard</option></select></div></div><label>Options (MCQ — one option per line)</label><textarea id="cQOptions${i}" class="input" rows="4" placeholder="Option A
Option B
Option C
Option D">${esc((q.options||[]).join('\n'))}</textarea><label>Correct answer</label><input id="cQAnswer${i}" class="input" value="${esc(q.answer||'')}" placeholder="Enter the correct answer"><label>Explanation (optional)</label><textarea id="cQExplanation${i}" class="input" rows="3" placeholder="Optional explanation for the learner...">${esc(q.explanation||'')}</textarea></div>`}
function assessments(s){if(!(can(s,'assessments.view')||can(s,'assignments.manage')||can(s,'assignments.manage_assigned')))return home();let editable=can(s,'assessments.manage')||can(s,'assignments.manage')||can(s,'assignments.manage_assigned');let rows=(s.assessments||[]).filter(x=>!isArchived(x));shell(s,'Assessments & Question Bank',nav(s,'Assessments')+`<div class="card"><h2>Assessment Centre</h2><p class="muted">Create the assessment and enter its questions before publishing. You can edit questions, answers, availability and assignments after creation.</p>${editable?`<div class="grid"><div><label>Assessment title</label><input id="assessmentTitle" class="input" placeholder="e.g. Term 1 Mathematics Test"></div><div><label>Subject</label><select id="assessmentSubject" class="input">${s.subjects.map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><div><label>Duration (minutes)</label><input id="assessmentDuration" class="input" type="number" value="30" min="1"></div><div><label>Pass mark (%)</label><input id="assessmentPass" class="input" type="number" value="50" min="0" max="100"></div><div style="grid-column:1/-1">${assignmentTargetControls(s).replace(/assignmentClasses/g,'assessmentClasses').replace(/assignmentStudents/g,'assessmentStudents')}</div><div style="grid-column:1/-1">${availabilityControls({},'assessment')}</div><div style="grid-column:1/-1"><label>Instructions</label><textarea id="assessmentInstructions" class="input" rows="4" placeholder="Instructions shown to the student"></textarea></div><div style="grid-column:1/-1"><h3>Questions</h3><p class="muted">This is where you type the actual examination questions.</p><div id="createAssessmentQuestionList"><p class="muted">No questions added yet.</p></div><button type="button" class="btn alt" onclick="addAssessmentCreateQuestion()">+ Add question</button></div><div style="grid-column:1/-1"><h3>Word document</h3><p class="muted">Optional: attach a .doc or .docx file instead of typing all content into the app.</p><input id="assessmentCreateFile" class="input" type="file" accept=".doc,.docx,application/msword,application/vnd.openxmlformats-officedocument.wordprocessingml.document"></div><button class="btn" onclick="createAssessment()">Create assessment</button></div>`:''}<div class="row" style="margin-top:14px"><button class="btn alt" onclick="assessmentArchived()">Archived assessments</button><button class="btn alt" onclick="page('Uploads')">Open Upload Centre</button></div><h3 style="margin-top:18px">Existing assessments</h3><table class="table"><tr><th>Title</th><th>Subject</th><th>Audience</th><th>Availability</th><th>Questions</th><th>Status</th><th>Action</th></tr>${rows.map(a=>`<tr><td>${esc(a.title)}</td><td>${esc(a.subject)}</td><td>${esc((a.classIds||[]).map(id=>s.classes.find(c=>c.id===id)?.name||id).join(', '))}${a.studentIds?.length?` + ${a.studentIds.length} student(s)`:''}</td><td>${esc(availabilityLabel(a))}</td><td>${(a.questionBank||[]).length}</td><td><span class="pill">${esc(a.status||'Draft')}</span></td><td><button class="btn" onclick="assessmentEditor('${a.id}')">Edit questions</button> <button class="btn alt" onclick="togglePublish('assessment','${a.id}')">${a.status==='Published'?'Unpublish':'Publish'}</button> ${lifecycleActions('assessment',a)}</td></tr>`).join('')||'<tr><td colspan="7">No assessments yet.</td></tr>'}</table></div>`);}
function addAssessmentCreateQuestion(){let box=document.getElementById('createAssessmentQuestionList');if(!box)return;let s=state();let count=box.querySelectorAll('.question-row').length;let q={type:'mcq',text:'',marks:1,difficulty:'Medium',options:['Option A','Option B'],answer:'',explanation:''};if(count===0)box.innerHTML='';box.insertAdjacentHTML('beforeend',assessmentCreateQuestionRow(q,count));}
function removeAssessmentCreateQuestion(i){let el=document.getElementById('createQuestion'+i);if(el)el.remove();}
function collectAssessmentCreateQuestions(){let rows=[...document.querySelectorAll('#createAssessmentQuestionList .question-row')];return rows.map((row,i)=>({id:'Q'+Date.now()+i,type:row.querySelector('[id^="cQType"]')?.value||'mcq',text:row.querySelector('[id^="cQText"]')?.value.trim()||'',marks:+row.querySelector('[id^="cQMarks"]')?.value||1,difficulty:row.querySelector('[id^="cQDiff"]')?.value||'Medium',options:(row.querySelector('[id^="cQOptions"]')?.value||'').split('\n').map(v=>v.trim()).filter(Boolean),answer:row.querySelector('[id^="cQAnswer"]')?.value.trim()||'',explanation:row.querySelector('[id^="cQExplanation"]')?.value.trim()||''}));}
async function createAssessment(){let s=state();if(!(can(s,'assessments.manage')||can(s,'assignments.manage')||can(s,'assignments.manage_assigned')))return;let questions=collectAssessmentCreateQuestions();let a={id:'A'+Date.now(),title:document.getElementById('assessmentTitle').value.trim(),subject:document.getElementById('assessmentSubject').value,duration:+document.getElementById('assessmentDuration').value,passMark:+document.getElementById('assessmentPass').value,instructions:document.getElementById('assessmentInstructions').value.trim(),classIds:selectedValues('assessmentClasses'),studentIds:selectedValues('assessmentStudents'),startAt:document.getElementById('assessmentStart').value?new Date(document.getElementById('assessmentStart').value).toISOString():null,endAt:document.getElementById('assessmentEnd').value?new Date(document.getElementById('assessmentEnd').value).toISOString():null,status:'Draft',questionBank:questions,versions:[],questions:questions.length,totalMarks:questions.reduce((n,q)=>n+(Number(q.marks)||0),0)};if(!a.title||!a.duration)return alert('Enter an assessment title and duration.');if(!a.classIds.length&&!a.studentIds.length)return alert('Assign the assessment to at least one class or student.');if(!a.questionBank.length)return alert('Add at least one question before creating the assessment.');if(a.questionBank.some(q=>!q.text))return alert('Every question must have question text.');if(a.startAt&&a.endAt&&a.startAt>=a.endAt)return alert('The end time must be later than the start time.');s.assessments=s.assessments||[];s.assessments.unshift(a);s.assessmentAssignments=s.assessmentAssignments||[];s.assessmentAssignments.unshift({assessmentId:a.id,classIds:a.classIds,studentIds:a.studentIds,startAt:a.startAt,endAt:a.endAt});auditAdd(s,`Created assessment ${a.title}`);save(s);let f=document.getElementById('assessmentCreateFile')?.files?.[0];if(f){try{await uploadDocument(f,'assessment',a.id)}catch(e){alert('Assessment created, but Word upload failed: '+e.message)}}assessmentEditor(a.id)}
function collectAssessmentQuestions(s,a){return (a.questionBank||[]).map((q,i)=>({id:q.id||'Q'+Date.now()+i,type:document.getElementById('qType'+i)?.value||q.type||'mcq',text:document.getElementById('qText'+i)?.value.trim()||'',marks:+document.getElementById('qMarks'+i)?.value||1,difficulty:document.getElementById('qDiff'+i)?.value||'Medium',options:(document.getElementById('qOptions'+i)?.value||'').split('\n').map(v=>v.trim()).filter(Boolean),answer:document.getElementById('qAnswer'+i)?.value.trim()||'',explanation:document.getElementById('qExplanation'+i)?.value.trim()||''}))}
function saveAssessmentEdit(id){let s=state(),a=s.assessments.find(x=>x.id===id);if(!a)return;let old=clone(a);delete old.versions;a.versions=a.versions||[];a.versions.unshift({...old,savedAt:new Date().toISOString()});a.title=document.getElementById('aeTitle').value.trim();a.subject=document.getElementById('aeSubject').value;a.duration=+document.getElementById('aeDuration').value;a.passMark=+document.getElementById('aePass').value;a.classIds=selectedValues('assessmentClasses');a.studentIds=selectedValues('assessmentStudents');a.startAt=document.getElementById('aeStart').value?new Date(document.getElementById('aeStart').value).toISOString():null;a.endAt=document.getElementById('aeEnd').value?new Date(document.getElementById('aeEnd').value).toISOString():null;a.questionBank=collectAssessmentQuestions(s,a);if(!a.title||!a.duration)return alert('Title and duration are required.');if(!a.classIds.length&&!a.studentIds.length)return alert('Assign to at least one class or student.');if(a.startAt&&a.endAt&&a.startAt>=a.endAt)return alert('The end time must be later than the start time.');a.questions=a.questionBank.length;a.totalMarks=a.questionBank.reduce((n,q)=>n+(Number(q.marks)||0),0);s.assessmentAssignments=s.assessmentAssignments||[];let target=s.assessmentAssignments.find(v=>v.assessmentId===id);if(target){target.classIds=a.classIds;target.studentIds=a.studentIds;target.startAt=a.startAt;target.endAt=a.endAt}else{s.assessmentAssignments.push({assessmentId:id,classIds:a.classIds,studentIds:a.studentIds,startAt:a.startAt,endAt:a.endAt})}auditAdd(s,`Edited assessment ${a.title}`);save(s);assessmentEditor(id)}
function addAssessmentQuestion(){let id=window.currentAssessmentEditorId,s=state(),a=s.assessments.find(x=>x.id===id);if(!a)return;a.questionBank=a.questionBank||[];a.questionBank.push({id:'Q'+Date.now(),type:'mcq',text:'',marks:1,difficulty:'Medium',options:['Option A','Option B'],answer:'',explanation:''});save(s);assessmentEditor(id)}
function removeAssessmentQuestion(i){let id=window.currentAssessmentEditorId,s=state(),a=s.assessments.find(x=>x.id===id);if(!a)return;a.questionBank=(a.questionBank||[]).filter((_,n)=>n!==i);save(s);assessmentEditor(id)}
function togglePublish(kind,id){let s=state(),arr=kind==='assessment'?s.assessments:s.assignments,x=arr.find(v=>v.id===id);if(!x)return;x.status=x.status==='Published'?'Draft':'Published';auditAdd(s,`${x.status==='Published'?'Published':'Unpublished'} ${kind} ${x.title}`);save(s);kind==='assessment'?assessmentEditor(id):editAssignment(id)}
function uploads(s){if(!(can(s,'uploads.manage')||can(s,'uploads.manage_assigned')))return home();let items=[...(s.assessments||[]).map(x=>({id:x.id,title:x.title,type:'assessment'})),...(s.assignments||[]).map(x=>({id:x.id,title:x.title,type:'assignment'}))];shell(s,'Upload Centre',nav(s,'Uploads')+`<div class="card"><h2>Word document upload</h2><p>Upload a .doc or .docx document and attach it to an assessment or assignment. The file is stored in the private DIS Academy Supabase Storage bucket.</p><div class="grid"><div><label>Content type</label><select id="upType" class="input" onchange="refreshUploadRecords()"><option value="assessment">Assessment</option><option value="assignment">Assignment</option></select></div><div><label>Assessment / assignment</label><select id="upRecord" class="input"></select></div><div><label>Word document</label><input id="upFile" class="input" type="file" accept=".doc,.docx,application/msword,application/vnd.openxmlformats-officedocument.wordprocessingml.document"></div></div><button class="btn" onclick="uploadFromCentre()">Upload document</button><div id="uploadStatus" class="notice" style="display:none"></div><h3 style="margin-top:18px">Uploaded documents</h3>${(s.documents||[]).map(d=>`<div class="notice"><b>${esc(d.name)}</b><br>${esc(d.entityType)} · ${esc(items.find(i=>i.id===d.entityId)?.title||d.entityId)} · ${new Date(d.createdAt).toLocaleString()}<br><button class="btn alt" onclick="downloadDocument('${d.id}')">Open / download</button></div>`).join('')||'<p>No documents uploaded yet.</p>'}</div>`);refreshUploadRecords()}
function refreshUploadRecords(){let s=state(),type=document.getElementById('upType')?.value||'assessment',sel=document.getElementById('upRecord');if(!sel)return;let arr=(type==='assessment'?s.assessments:s.assignments)||[];sel.innerHTML=arr.filter(x=>!isArchived(x)).map(x=>`<option value="${x.id}">${esc(x.title)}</option>`).join('')}
async function uploadForRecord(inputId,kind,id){let f=document.getElementById(inputId)?.files?.[0];if(!f)return alert('Choose a Word document first.');try{await uploadDocument(f,kind,id);let s=state();if(kind==='assessment')assessmentEditor(id);else if(kind==='assignment')editAssignment(id);else if(kind==='lesson')editLesson(id)}catch(e){alert('Upload failed: '+e.message)}}
function department(s){if(!guard(s,'students.view'))return home();let u=userObj(s),rows=s.students.filter(x=>u.classes?.includes(x.classId));shell(s,'Department / Year Group',nav(s,'Department')+`<div class="card"><p>Department: <b>${esc(u.department||'Assigned')}</b></p><table class="table"><tr><th>Student</th><th>Class</th><th>Average</th></tr>${rows.map(x=>`<tr><td>${esc(x.name)}</td><td>${x.classId}</td><td>${x.avg}%</td></tr>`).join('')}</table></div>`)}
function visibleMessages(s){let u=userObj(s);return s.messages.filter(m=>{if(u.role==='Admin'||u.role==='SuperAdmin')return can(s,'messages.view_all');if(u.role==='Parent')return m.from===u.id||m.to===u.id; if(u.role==='Teacher')return m.from===u.id||m.to===u.id|| (m.type==='parent-teacher'&&m.studentId&&u.classes?.includes(s.students.find(st=>st.id===m.studentId)?.classId)); if(u.role==='HOD')return m.from===u.id||m.to===u.id||m.type==='parent-teacher'; if(u.role==='Bursar')return m.from===u.id||m.to===u.id||m.type==='finance';return m.from===u.id||m.to===u.id})}
function messages(s){let rows=visibleMessages(s);shell(s,'Messages',nav(s,s.user.role==='Teacher'||s.user.role==='HOD'?'Parent Messages':'Messages')+`<div class="card"><h2>Communication inbox</h2><p class="muted">Parent-teacher conversations are visible to the relevant teacher. Administration has school-wide oversight; ordinary conversations do not clutter the admin inbox.</p><div class="row"><select id="msgTo">${s.users.filter(u=>u.id!==userObj(s).id&&(['Admin','Teacher','HOD','Parent'].includes(u.role))).map(u=>`<option value="${u.id}">${esc(u.name)} — ${u.role}</option>`).join('')}</select><input id="msgSubject" class="input" placeholder="Subject"><input id="msgBody" class="input" placeholder="Message"><button class="btn" onclick="sendMessage()">Send</button></div><table class="table"><tr><th>Date</th><th>From</th><th>To</th><th>Subject</th><th>Message</th><th>Status</th></tr>${rows.map(m=>`<tr><td>${m.date}</td><td>${esc(s.users.find(u=>u.id===m.from)?.name||m.from)}</td><td>${esc(s.users.find(u=>u.id===m.to)?.name||m.to)}</td><td>${esc(m.subject)}</td><td>${esc(m.body)}</td><td><span class="pill">${m.status}</span></td></tr>`).join('')}</table></div>`)}
function sendMessage(){let s=state(),u=userObj(s),to=document.getElementById('msgTo').value,sub=document.getElementById('msgSubject').value.trim(),body=document.getElementById('msgBody').value.trim();if(!sub||!body)return alert('Enter a subject and message.');if(u.role==='Parent'&&!s.users.find(x=>x.id===to))return;let recipient=s.users.find(x=>x.id===to);if(!recipient)return;let type=(u.role==='Parent'&&recipient.role==='Admin')?'parent-admin':(u.role==='Parent'?'parent-teacher':'general');s.messages.unshift({id:'M'+Date.now(),from:u.id,to,subject:sub,body,date:new Date().toLocaleString(),status:'Open',studentId:u.childIds?.[0]||userObj(s).studentId||null,type});save(s);messages(s)}
function userNotifications(s){let u=userObj(s);return s.notifications.filter(n=>n.audience==='school'||n.userId===u.id||n.audience===u.role.toLowerCase())}function notifications(s){let rows=userNotifications(s);shell(s,'Notifications',nav(s,'Notifications')+`<div class="card">${rows.map(n=>`<div class="notice"><b>${esc(n.title)}</b><br>${esc(n.body)}<small>${esc(n.date)}</small></div>`).join('')||'<p>No notifications.</p>'}</div>`)}
function childProgress(s){let u=userObj(s),children=s.students.filter(x=>u.childIds?.includes(x.id));shell(s,'Child Progress',nav(s,'Child Progress')+children.map(c=>`<div class="card"><h2>${esc(c.name)}</h2><p>Average: <b>${c.avg}%</b></p><h3>Recent results</h3>${s.results.filter(r=>r.student===c.name).map(r=>`<p>${esc(r.assessment)} — ${r.score}%</p>`).join('')||'<p>No results.</p>'}</div>`).join(''))}
function changePasswordDialog(){
 const current=prompt('Enter your current password:'); if(current===null)return;
 const next=prompt('Enter your new password (minimum 8 characters):'); if(next===null)return;
 const confirm=prompt('Confirm your new password:'); if(confirm===null)return;
 if(next.length<8)return alert('Use at least 8 characters.');
 if(next!==confirm)return alert('The new passwords do not match.');
 api('/api/auth/change-password',{method:'POST',body:JSON.stringify({currentPassword:current,newPassword:next})}).then(()=>alert('Password changed successfully.')).catch(e=>alert(e.message||'Unable to change password.'));
}
function accounts(s){if(!guard(s,'accounts.manage'))return home();
 const staffRoles=['Teacher','HOD','Bursar','Staff'];
 shell(s,'Account Management',nav(s,'Accounts')+`<div class="card"><h2>Create account</h2><p class="muted">Choose either an email invitation, which lets the recipient create their password, or a temporary password that the recipient can change after signing in.</p>
 <div class="grid"><div><label>Full name</label><input id="acctName" class="input" placeholder="Full name"></div><div><label>Email address</label><input id="acctEmail" class="input" type="email" placeholder="person@example.com"></div><div><label>Role</label><select id="acctRole" class="input" onchange="refreshAccountProfileFields()"><option>Student</option><option>Parent</option>${staffRoles.map(r=>`<option>${r}</option>`).join('')}</select></div><div><label>Account method</label><select id="acctMethod" class="input" onchange="refreshAccountProfileFields()"><option value="invite">Send email invitation</option><option value="temporary">Create temporary password</option></select></div><div id="acctProfileFields" style="grid-column:1/-1"></div><div id="acctTempWrap" style="display:none"><label>Temporary password</label><input id="acctTemp" class="input" type="text" minlength="8" placeholder="At least 8 characters"></div><button class="btn" onclick="createAccount()">Create account</button></div></div>
 <div class="card"><h2>Linked accounts</h2><table class="table"><tr><th>Name</th><th>Email</th><th>Role</th><th>Linked record</th><th>Status</th></tr>${(s.users||[]).filter(u=>u.email||u.authUserId).map(u=>`<tr><td>${esc(u.name)}</td><td>${esc(u.email||'—')}</td><td>${esc(u.role)}</td><td>${esc(u.studentId||u.staffId||(u.childIds||[]).join(', ')||'—')}</td><td><span class="pill">${esc(u.status||'Active')}</span></td></tr>`).join('')||'<tr><td colspan="5">No linked production accounts recorded in this browser yet.</td></tr>'}</table></div>`);
 refreshAccountProfileFields();
}
function refreshAccountProfileFields(){const role=document.getElementById('acctRole')?.value,box=document.getElementById('acctProfileFields'),wrap=document.getElementById('acctTempWrap'),method=document.getElementById('acctMethod')?.value;if(!box)return; if(wrap)wrap.style.display=method==='temporary'?'block':'none';
 const s=state(); if(role==='Student'){box.innerHTML=`<label>Student record</label><select id="acctStudent" class="input">${activeItems(s.students).map(x=>`<option value="${esc(x.id)}">${esc(x.name)} — ${esc(x.classId)}</option>`).join('')}</select>`}
 else if(role==='Parent'){box.innerHTML=`<label>Child / children</label><select id="acctChildren" class="input" multiple size="5">${activeItems(s.students).map(x=>`<option value="${esc(x.id)}">${esc(x.name)} — ${esc(x.classId)}</option>`).join('')}</select>`}
 else {box.innerHTML=`<label>Staff record (optional)</label><select id="acctStaff" class="input"><option value="">Create login without linking a staff record yet</option>${activeItems(s.staff).filter(x=>['Teacher','HOD','Bursar','Staff'].includes(x.role)).map(x=>`<option value="${esc(x.id)}">${esc(x.name)} — ${esc(x.role)}</option>`).join('')}</select>`}
}
async function createAccount(){let s=state();if(!guard(s,'accounts.manage'))return;const name=document.getElementById('acctName').value.trim(),email=document.getElementById('acctEmail').value.trim().toLowerCase(),role=document.getElementById('acctRole').value,method=document.getElementById('acctMethod').value;if(!name||!/^\S+@\S+\.\S+$/.test(email))return alert('Enter a valid name and email address.');let meta={name,role,schoolId:s.user.schoolId||'DIS'};if(role==='Student'){meta.studentId=document.getElementById('acctStudent')?.value;if(!meta.studentId)return alert('Select the student record.');}else if(role==='Parent'){meta.childIds=selectedValues('acctChildren');if(!meta.childIds.length)return alert('Select at least one child.');}else{meta.staffId=document.getElementById('acctStaff')?.value||null;}
 const button=document.querySelector('#acctTempWrap')?.parentElement?.querySelector('button.btn'); if(button){button.disabled=true;button.textContent=method==='invite'?'Sending invitation…':'Creating account…';} try{let d;if(method==='invite'){d=await api('/api/admin/invite-user',{method:'POST',body:JSON.stringify({email,name,role,meta,id:role==='Student'?meta.studentId:(meta.staffId||undefined)})});}else{const password=document.getElementById('acctTemp').value;if(password.length<8)return alert('Temporary password must contain at least 8 characters.');d=await api('/api/admin/provision-user',{method:'POST',body:JSON.stringify({email,password,name,role,meta,id:role==='Student'?meta.studentId:(meta.staffId||undefined)})});}
 let u={id:d.user?.id||meta.studentId||meta.staffId||('AUTH-'+Date.now()),username:email.split('@')[0],name,email,role,status:'Active',authUserId:d.user?.authUserId,studentId:meta.studentId,childIds:meta.childIds,staffId:meta.staffId};s.users=s.users||[];s.users=s.users.filter(x=>x.email!==email);s.users.push(u);if(role==='Student'){const st=s.students.find(x=>x.id===meta.studentId);if(st)st.userId=u.id;}if(role==='Parent'){for(const cid of meta.childIds){const st=s.students.find(x=>x.id===cid);if(st)st.parentUser=u.id;}}save(s);alert(method==='invite'?'Invitation sent. The recipient should use the email to set their password.':'Account created. Give the recipient the temporary password and ask them to change it after signing in.');accounts(s);
 }catch(e){const msg=e?.message||'Unable to create account.'; alert(msg==='Failed to fetch' ? 'DIS Academy could not reach the production API. Confirm that the DIS Academy API URL is configured in the app and that the server is online. No account was confirmed as created.' : msg);} finally {const button=document.querySelector('#acctTempWrap')?.parentElement?.querySelector('button.btn'); if(button){button.disabled=false;button.textContent='Create account';}}}

function permissions(s){if(!guard(s,'permissions.manage'))return home();let roles=Object.keys(s.permissions).filter(r=>r!=='SuperAdmin');let perms=[...new Set(Object.values(s.permissions).flat().filter(x=>x!=='*'))];shell(s,'Role & Permission Management',nav(s,'Permissions')+`<div class="card"><p><b>Deny by default.</b> Changes affect what each role can access. Server-side enforcement is required when this prototype is connected to the production API.</p><table class="table"><tr><th>Permission</th>${roles.map(r=>`<th>${r}</th>`).join('')}</tr>${perms.map(p=>`<tr><td>${p}</td>${roles.map(r=>`<td><input type="checkbox" ${s.permissions[r]?.includes(p)?'checked':''} onchange="togglePerm('${r}','${p}',this.checked)"></td>`).join('')}</tr>`).join('')}</table></div>`)}
function togglePerm(role,p,on){let s=state();if(!guard(s,'permissions.manage'))return;if(!s.permissions[role])s.permissions[role]=[];s.permissions[role]=on?[...new Set([...s.permissions[role],p])]:s.permissions[role].filter(x=>x!==p);auditAdd(s,`${on?'Granted':'Revoked'} ${p} for ${role}`);save(s);permissions(s)}
function auditAdd(s,action){s.audit.unshift({date:new Date().toLocaleString(),actor:s.user?.name||'System',action})}
if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{});
// Production heartbeat: while the portal is open, keep the application/database active and visible.
setInterval(()=>{if(navigator.onLine){const base=(window.DIS_API_BASE_URL||localStorage.getItem('DIS_API_BASE_URL')||'').trim().replace(/\/$/,'');if(base)fetch(base+'/api/health',{credentials:'include',cache:'no-store',headers:{'X-DIS-App':'android-2.2.4'}}).catch(()=>{});}},5*60*1000);
home();
